"""Physics practicals for classes 11–12 (CBSE/NCERT and Karnataka PUC) and
degree labs: optics, mechanics, heat, sound and modern physics."""


def add(lab, W, Q):
    BENCH = W('Optical bench with uprights', 'उपस्तंभों सहित प्रकाशिक बेंच', 'ಆಧಾರ ಕಂಬಗಳ ಸಹಿತ ದೃಕ್ ಪೀಠ')
    NEEDLES = W('Two optical needles (object and image)', 'दो प्रकाशिक सुइयाँ (वस्तु और प्रतिबिंब)', 'ಎರಡು ದೃಕ್ ಸೂಜಿಗಳು (ವಸ್ತು ಮತ್ತು ಪ್ರತಿಬಿಂಬ)')
    SCALE = W('Metre scale', 'मीटर पैमाना', 'ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ')
    STOPWATCH = W('Stopwatch', 'विराम घड़ी', 'ನಿಲುಗಡಿಯಾರ')
    WEIGHTS = W('Slotted weights (50 g each) with hanger', 'हैंगर सहित खाँचेदार बाट (हर एक 50 g)', 'ಹ್ಯಾಂಗರ್ ಸಹಿತ ಸೀಳು ತೂಕಗಳು (ಪ್ರತಿ 50 g)')
    RHEO = W('Rheostat', 'धारा नियंत्रक (रिओस्टेट)', 'ರಿಯೋಸ್ಟಾಟ್')
    STAND = W('Rigid stand with clamp', 'क्लैंप सहित दृढ़ स्टैंड', 'ಕ್ಲ್ಯಾಂಪ್ ಸಹಿತ ದೃಢ ಸ್ಟ್ಯಾಂಡ್')
    P_PARALLAX = W('Remove parallax tip to tip, keeping the eye at least 25 cm from the needle.', 'आँख को सुई से कम से कम 25 cm दूर रखकर नोक से नोक का लंबन हटाएँ।', 'ಕಣ್ಣನ್ನು ಸೂಜಿಯಿಂದ ಕನಿಷ್ಠ 25 cm ದೂರವಿಟ್ಟು ತುದಿಯಿಂದ ತುದಿಗೆ ಭ್ರಂಶ ತೆಗೆಯಿರಿ.')
    P_ALIGN = W('Keep the tips of the needles and the centre of the lens or mirror at the same height.', 'सुइयों की नोकें और लेंस या दर्पण का केंद्र एक ही ऊँचाई पर रखें।', 'ಸೂಜಿಗಳ ತುದಿಗಳು ಮತ್ತು ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ.')
    P_INDEX = W('Apply the index correction between the bench scale and the actual distance.', 'बेंच पैमाने और वास्तविक दूरी के बीच सूचकांक संशोधन लगाएँ।', 'ಪೀಠದ ಅಳತೆ ಮತ್ತು ನಿಜ ದೂರದ ನಡುವಿನ ಸೂಚ್ಯಂಕ ತಿದ್ದುಪಡಿ ಅನ್ವಯಿಸಿ.')
    P_ZERO = W('Check the zero error of every instrument before you start.', 'शुरू करने से पहले हर उपकरण की शून्य त्रुटि जाँचें।', 'ಆರಂಭಿಸುವ ಮೊದಲು ಪ್ರತಿ ಉಪಕರಣದ ಶೂನ್ಯ ದೋಷ ಪರಿಶೀಲಿಸಿ.')
    P_REPEAT = W('Repeat each reading and take the mean.', 'हर पाठ्यांक दोहराएँ और माध्य लें।', 'ಪ್ರತಿ ಓದನ್ನು ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.')
    CSV = W('Export the readings as CSV and work out the uncertainty from the fit.', 'पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।', 'ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ.')

    # ------------------------------------------------------------- optics
    uv_common = dict(bench='optical-bench', subject='Physics', domain='physics', levels=[12], curricula=['cbse', 'ncert', 'ka-puc'])
    lab(id='convex-lens-uv', setup={'task': 'lens-uv'}, **uv_common,
        keywords=['ray optics', 'convex lens', 'focal length', 'u-v method', 'lens formula', 'optical instruments'],
        title=W('Focal length of a convex lens (u–v method)', 'उत्तल लेंस की फ़ोकस दूरी (u–v विधि)', 'ಪೀನ ಮಸೂರದ ನಾಭಿದೂರ (u–v ವಿಧಾನ)'),
        summary=W('Find v for several u by removing parallax, then f from uv/(u + v) and from the 1/v–1/u graph.', 'कई u के लिए लंबन हटाकर v ज्ञात करें, फिर uv/(u + v) से और 1/v–1/u ग्राफ़ से f निकालें।', 'ಹಲವು u ಗೆ ಭ್ರಂಶ ತೆಗೆದು v ಕಂಡುಹಿಡಿಯಿರಿ, ನಂತರ uv/(u + v) ಮತ್ತು 1/v–1/u ನಕ್ಷೆಯಿಂದ f ಪಡೆಯಿರಿ.'),
        aim=W('To find the focal length of a convex lens by plotting graphs between u and v and between 1/u and 1/v.', 'u और v के बीच तथा 1/u और 1/v के बीच ग्राफ़ बनाकर उत्तल लेंस की फ़ोकस दूरी ज्ञात करना।', 'u ಮತ್ತು v ನಡುವೆ ಹಾಗೂ 1/u ಮತ್ತು 1/v ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ಪೀನ ಮಸೂರದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('For a convex lens 1/v + 1/u = 1/f, taking the distances of the real object and real image as positive. So f = uv/(u + v), and the graph of 1/v against 1/u is a straight line cutting both axes at 1/f.', 'उत्तल लेंस के लिए, वास्तविक वस्तु और वास्तविक प्रतिबिंब की दूरियाँ धनात्मक लेने पर, 1/v + 1/u = 1/f. अतः f = uv/(u + v), और 1/v तथा 1/u का ग्राफ़ एक सीधी रेखा है जो दोनों अक्षों को 1/f पर काटती है।', 'ನೈಜ ವಸ್ತು ಮತ್ತು ನೈಜ ಪ್ರತಿಬಿಂಬದ ದೂರಗಳನ್ನು ಧನಾತ್ಮಕವಾಗಿ ತೆಗೆದುಕೊಂಡರೆ ಪೀನ ಮಸೂರಕ್ಕೆ 1/v + 1/u = 1/f. ಆದ್ದರಿಂದ f = uv/(u + v); 1/v ಮತ್ತು 1/u ನಕ್ಷೆ ಎರಡೂ ಅಕ್ಷಗಳನ್ನು 1/f ನಲ್ಲಿ ಛೇದಿಸುವ ಸರಳರೇಖೆ.'),
        apparatus=[BENCH, W('Convex lens with holder', 'धारक सहित उत्तल लेंस', 'ಹಿಡಿಕೆ ಸಹಿತ ಪೀನ ಮಸೂರ'), NEEDLES, W('Index needle', 'सूचक सुई', 'ಸೂಚ್ಯಂಕ ಸೂಜಿ')],
        steps=[W('Find the rough focal length by focusing a distant object on a wall.', 'दूर की वस्तु को दीवार पर फ़ोकस करके मोटी फ़ोकस दूरी ज्ञात करें।', 'ದೂರದ ವಸ್ತುವನ್ನು ಗೋಡೆಯ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ ಸುಮಾರು ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Fix the lens. Put the object needle at a distance u between f and 2f, or beyond 2f.', 'लेंस स्थिर करें। वस्तु सुई को f और 2f के बीच, या 2f से परे, दूरी u पर रखें।', 'ಮಸೂರ ಸ್ಥಿರಗೊಳಿಸಿ. ವಸ್ತು ಸೂಜಿಯನ್ನು f ಮತ್ತು 2f ನಡುವೆ ಅಥವಾ 2f ಆಚೆ u ದೂರದಲ್ಲಿಡಿ.'),
               W('Look through the lens from the other side and move the image needle until its tip and the inverted image have no parallax. Record v.', 'दूसरी ओर से लेंस में देखें और प्रतिबिंब सुई को तब तक खिसकाएँ जब तक उसकी नोक और उल्टे प्रतिबिंब में लंबन न रहे। v लिखें।', 'ಇನ್ನೊಂದು ಕಡೆಯಿಂದ ಮಸೂರದಲ್ಲಿ ನೋಡಿ, ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯ ತುದಿ ಮತ್ತು ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬದ ನಡುವೆ ಭ್ರಂಶ ಇಲ್ಲದವರೆಗೆ ಅದನ್ನು ಸರಿಸಿ. v ದಾಖಲಿಸಿ.'),
               W('Repeat for five or six values of u.', 'u के पाँच-छह मानों के लिए दोहराएँ।', 'u ನ ಐದು-ಆರು ಮೌಲ್ಯಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Work out f for each pair, and plot 1/v against 1/u.', 'हर युग्म के लिए f निकालें, और 1/v तथा 1/u का ग्राफ़ बनाएँ।', 'ಪ್ರತಿ ಜೋಡಿಗೆ f ಲೆಕ್ಕಿಸಿ, 1/v ಮತ್ತು 1/u ನಕ್ಷೆ ಎಳೆಯಿರಿ.')],
        precautions=[P_ALIGN, P_PARALLAX, P_INDEX],
        conclusion=W('The values of uv/(u + v) agree, and the 1/v–1/u graph is a straight line with equal intercepts 1/f on both axes, giving the focal length of the lens.', 'uv/(u + v) के मान मेल खाते हैं, और 1/v–1/u ग्राफ़ दोनों अक्षों पर समान अंतःखंड 1/f वाली सीधी रेखा है, जिससे लेंस की फ़ोकस दूरी मिलती है।', 'uv/(u + v) ಮೌಲ್ಯಗಳು ಹೊಂದುತ್ತವೆ; 1/v–1/u ನಕ್ಷೆ ಎರಡೂ ಅಕ್ಷಗಳಲ್ಲಿ ಸಮ ಅಂತಃಖಂಡ 1/f ಇರುವ ಸರಳರೇಖೆ; ಅದರಿಂದ ಮಸೂರದ ನಾಭಿದೂರ ಸಿಗುತ್ತದೆ.'),
        viva=[Q(W('What is parallax?', 'लंबन क्या है?', 'ಭ್ರಂಶ ಎಂದರೇನು?'), W('The apparent shift of one object against another when the eye moves sideways.', 'आँख को बगल में हिलाने पर एक वस्तु का दूसरी के सापेक्ष आभासी खिसकाव।', 'ಕಣ್ಣನ್ನು ಪಕ್ಕಕ್ಕೆ ಸರಿಸಿದಾಗ ಒಂದು ವಸ್ತು ಇನ್ನೊಂದರ ಸಾಪೇಕ್ಷವಾಗಿ ಸರಿದಂತೆ ಕಾಣುವುದು.')),
              Q(W('Where is the object when u = v?', 'u = v होने पर वस्तु कहाँ है?', 'u = v ಆದಾಗ ವಸ್ತು ಎಲ್ಲಿದೆ?'), W('At 2F: both are 2f.', '2F पर: दोनों 2f हैं।', '2F ನಲ್ಲಿ: ಎರಡೂ 2f.')),
              Q(W('What is the power of a lens of focal length 20 cm?', '20 cm फ़ोकस दूरी वाले लेंस की क्षमता कितनी है?', '20 cm ನಾಭಿದೂರದ ಮಸೂರದ ಸಾಮರ್ಥ್ಯ ಎಷ್ಟು?'), W('+5 dioptre.', '+5 डायोप्टर।', '+5 ಡಯಾಪ್ಟರ್.'))])

    lab(id='concave-mirror-uv', setup={'task': 'mirror-uv'}, **uv_common,
        keywords=['ray optics', 'concave mirror', 'focal length', 'u-v method', 'mirror formula', 'reflection'],
        title=W('Focal length of a concave mirror (u–v method)', 'अवतल दर्पण की फ़ोकस दूरी (u–v विधि)', 'ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ (u–v ವಿಧಾನ)'),
        summary=W('Locate the real image of a needle in a concave mirror for several u and find f.', 'कई u के लिए अवतल दर्पण में सुई का वास्तविक प्रतिबिंब ढूँढें और f ज्ञात करें।', 'ಹಲವು u ಗೆ ನಿಮ್ನ ದರ್ಪಣದಲ್ಲಿ ಸೂಜಿಯ ನೈಜ ಪ್ರತಿಬಿಂಬ ಹುಡುಕಿ f ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the focal length of a concave mirror by plotting graphs between u and v and between 1/u and 1/v.', 'u और v के बीच तथा 1/u और 1/v के बीच ग्राफ़ बनाकर अवतल दर्पण की फ़ोकस दूरी ज्ञात करना।', 'u ಮತ್ತು v ನಡುವೆ ಹಾಗೂ 1/u ಮತ್ತು 1/v ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('For a concave mirror forming a real image, 1/u + 1/v = 1/f with u and v measured in front of the mirror. When the object is at C (u = 2f) the image coincides with it.', 'वास्तविक प्रतिबिंब बनाते अवतल दर्पण के लिए, दर्पण के सामने मापे गए u और v से 1/u + 1/v = 1/f. वस्तु C पर (u = 2f) हो तो प्रतिबिंब उसी पर बनता है।', 'ನೈಜ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸುವ ನಿಮ್ನ ದರ್ಪಣಕ್ಕೆ, ದರ್ಪಣದ ಮುಂದೆ ಅಳೆದ u ಮತ್ತು v ಯಿಂದ 1/u + 1/v = 1/f. ವಸ್ತು C ನಲ್ಲಿದ್ದರೆ (u = 2f) ಪ್ರತಿಬಿಂಬ ಅದರ ಮೇಲೆಯೇ ಮೂಡುತ್ತದೆ.'),
        apparatus=[BENCH, W('Concave mirror with holder', 'धारक सहित अवतल दर्पण', 'ಹಿಡಿಕೆ ಸಹಿತ ನಿಮ್ನ ದರ್ಪಣ'), NEEDLES, W('Index needle', 'सूचक सुई', 'ಸೂಚ್ಯಂಕ ಸೂಜಿ')],
        steps=[W('Find the rough focal length by focusing a distant object.', 'दूर की वस्तु फ़ोकस करके मोटी फ़ोकस दूरी ज्ञात करें।', 'ದೂರದ ವಸ್ತುವನ್ನು ಕೇಂದ್ರೀಕರಿಸಿ ಸುಮಾರು ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Place the object needle beyond F in front of the mirror.', 'वस्तु सुई को दर्पण के सामने F से परे रखें।', 'ವಸ್ತು ಸೂಜಿಯನ್ನು ದರ್ಪಣದ ಮುಂದೆ F ಆಚೆ ಇಡಿ.'),
               W('Move the image needle until it has no parallax with the inverted image. Record u and v.', 'प्रतिबिंब सुई को तब तक खिसकाएँ जब तक उल्टे प्रतिबिंब से लंबन न रहे। u और v लिखें।', 'ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬದೊಂದಿಗೆ ಭ್ರಂಶ ಇಲ್ಲದವರೆಗೆ ಪ್ರತಿಬಿಂಬ ಸೂಜಿ ಸರಿಸಿ. u ಮತ್ತು v ದಾಖಲಿಸಿ.'),
               W('Repeat for five or six positions of the object.', 'वस्तु की पाँच-छह स्थितियों के लिए दोहराएँ।', 'ವಸ್ತುವಿನ ಐದು-ಆರು ಸ್ಥಾನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Find f from each pair and from the 1/v–1/u graph.', 'हर युग्म से और 1/v–1/u ग्राफ़ से f ज्ञात करें।', 'ಪ್ರತಿ ಜೋಡಿಯಿಂದ ಮತ್ತು 1/v–1/u ನಕ್ಷೆಯಿಂದ f ಕಂಡುಹಿಡಿಯಿರಿ.')],
        precautions=[P_ALIGN, P_PARALLAX, W('Keep the mirror clean and fixed at the end of the bench.', 'दर्पण साफ़ रखें और बेंच के सिरे पर स्थिर रखें।', 'ದರ್ಪಣವನ್ನು ಸ್ವಚ್ಛವಾಗಿ, ಪೀಠದ ತುದಿಯಲ್ಲಿ ಸ್ಥಿರವಾಗಿಡಿ.')],
        conclusion=W('uv/(u + v) is the same for every position and the 1/v–1/u graph gives the same f: the mirror formula holds.', 'हर स्थिति के लिए uv/(u + v) समान है और 1/v–1/u ग्राफ़ वही f देता है: दर्पण सूत्र सत्य है।', 'ಪ್ರತಿ ಸ್ಥಾನಕ್ಕೂ uv/(u + v) ಒಂದೇ; 1/v–1/u ನಕ್ಷೆ ಅದೇ f ನೀಡುತ್ತದೆ: ದರ್ಪಣ ಸೂತ್ರ ಸತ್ಯ.'),
        viva=[Q(W('How are f and R related for a spherical mirror?', 'गोलीय दर्पण के लिए f और R में क्या संबंध है?', 'ಗೋಳೀಯ ದರ್ಪಣಕ್ಕೆ f ಮತ್ತು R ನಡುವಿನ ಸಂಬಂಧ ಏನು?'), W('f = R/2.', 'f = R/2.', 'f = R/2.')),
              Q(W('Can a concave mirror form a virtual image?', 'क्या अवतल दर्पण आभासी प्रतिबिंब बना सकता है?', 'ನಿಮ್ನ ದರ್ಪಣ ಮಿಥ್ಯ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸಬಲ್ಲದೇ?'), W('Yes, when the object is between F and the pole.', 'हाँ, जब वस्तु F और ध्रुव के बीच हो।', 'ಹೌದು, ವಸ್ತು F ಮತ್ತು ಧ್ರುವದ ನಡುವೆ ಇದ್ದಾಗ.')),
              Q(W('Why do dentists use concave mirrors?', 'दंत चिकित्सक अवतल दर्पण क्यों प्रयोग करते हैं?', 'ದಂತವೈದ್ಯರು ನಿಮ್ನ ದರ್ಪಣ ಏಕೆ ಬಳಸುತ್ತಾರೆ?'), W('Held close to the tooth, it gives an erect, magnified image.', 'दाँत के पास रखने पर यह सीधा, बड़ा प्रतिबिंब देता है।', 'ಹಲ್ಲಿನ ಹತ್ತಿರ ಹಿಡಿದಾಗ ಅದು ನೇರ, ದೊಡ್ಡ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತದೆ.'))])

    lab(id='concave-lens-focal', setup={'task': 'concave-lens', 'item': 'A', 'u': 50.0}, **uv_common,
        keywords=['ray optics', 'concave lens', 'focal length', 'combination of lenses', 'lenses in contact'],
        title=W('Focal length of a concave lens (with a convex lens)', 'अवतल लेंस की फ़ोकस दूरी (उत्तल लेंस की सहायता से)', 'ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ (ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ)'),
        summary=W('A concave lens alone gives no real image; put it in contact with a stronger convex lens and use the combination.', 'अकेला अवतल लेंस वास्तविक प्रतिबिंब नहीं देता; उसे अधिक प्रबल उत्तल लेंस के संपर्क में रखकर संयोजन का प्रयोग करें।', 'ನಿಮ್ನ ಮಸೂರ ಒಂದೇ ನೈಜ ಪ್ರತಿಬಿಂಬ ನೀಡುವುದಿಲ್ಲ; ಹೆಚ್ಚು ಪ್ರಬಲ ಪೀನ ಮಸೂರದ ಸಂಪರ್ಕದಲ್ಲಿಟ್ಟು ಸಂಯೋಜನೆಯನ್ನು ಬಳಸಿ.'),
        aim=W('To find the focal length of a concave lens using a convex lens in contact with it.', 'संपर्क में रखे उत्तल लेंस की सहायता से अवतल लेंस की फ़ोकस दूरी ज्ञात करना।', 'ಸಂಪರ್ಕದಲ್ಲಿರುವ ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Lenses in contact add their powers: 1/F = 1/f₁ + 1/f₂. If the convex lens (f₁ = 10 cm here) is stronger, the pair is converging and its F can be found by the u–v method; then 1/f₂ = 1/F − 1/f₁, which comes out negative for the concave lens.', 'संपर्क में रखे लेंसों की क्षमताएँ जुड़ती हैं: 1/F = 1/f₁ + 1/f₂. यदि उत्तल लेंस (यहाँ f₁ = 10 cm) अधिक प्रबल हो तो युग्म अभिसारी होता है और u–v विधि से उसकी F ज्ञात की जा सकती है; तब 1/f₂ = 1/F − 1/f₁, जो अवतल लेंस के लिए ऋणात्मक आती है।', 'ಸಂಪರ್ಕದಲ್ಲಿರುವ ಮಸೂರಗಳ ಸಾಮರ್ಥ್ಯಗಳು ಕೂಡುತ್ತವೆ: 1/F = 1/f₁ + 1/f₂. ಪೀನ ಮಸೂರ (ಇಲ್ಲಿ f₁ = 10 cm) ಹೆಚ್ಚು ಪ್ರಬಲವಾಗಿದ್ದರೆ ಜೋಡಿ ಅಭಿಸರಣ; u–v ವಿಧಾನದಿಂದ ಅದರ F ಕಂಡುಹಿಡಿಯಬಹುದು; ನಂತರ 1/f₂ = 1/F − 1/f₁, ನಿಮ್ನ ಮಸೂರಕ್ಕೆ ಇದು ಋಣ.'),
        apparatus=[BENCH, W('Convex lens of known focal length (10 cm)', 'ज्ञात फ़ोकस दूरी (10 cm) का उत्तल लेंस', 'ತಿಳಿದ ನಾಭಿದೂರದ (10 cm) ಪೀನ ಮಸೂರ'), W('Concave lens', 'अवतल लेंस', 'ನಿಮ್ನ ಮಸೂರ'), NEEDLES],
        steps=[W('Put the concave lens in close contact with the convex lens in one holder.', 'अवतल लेंस को एक ही धारक में उत्तल लेंस के निकट संपर्क में रखें।', 'ನಿಮ್ನ ಮಸೂರವನ್ನು ಒಂದೇ ಹಿಡಿಕೆಯಲ್ಲಿ ಪೀನ ಮಸೂರದೊಂದಿಗೆ ನಿಕಟ ಸಂಪರ್ಕದಲ್ಲಿಡಿ.'),
               W('Place the object needle at a distance u from the combination.', 'वस्तु सुई को संयोजन से दूरी u पर रखें।', 'ವಸ್ತು ಸೂಜಿಯನ್ನು ಸಂಯೋಜನೆಯಿಂದ u ದೂರದಲ್ಲಿಡಿ.'),
               W('Find the real image with the image needle by removing parallax; record v.', 'लंबन हटाकर प्रतिबिंब सुई से वास्तविक प्रतिबिंब ढूँढें; v लिखें।', 'ಭ್ರಂಶ ತೆಗೆದು ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯಿಂದ ನೈಜ ಪ್ರತಿಬಿಂಬ ಹುಡುಕಿ; v ದಾಖಲಿಸಿ.'),
               W('Repeat for several u and find F = uv/(u + v).', 'कई u के लिए दोहराएँ और F = uv/(u + v) ज्ञात करें।', 'ಹಲವು u ಗೆ ಪುನರಾವರ್ತಿಸಿ F = uv/(u + v) ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out f₂ = F f₁ ÷ (f₁ − F).', 'f₂ = F f₁ ÷ (f₁ − F) निकालें।', 'f₂ = F f₁ ÷ (f₁ − F) ಲೆಕ್ಕಿಸಿ.')],
        precautions=[P_ALIGN, P_PARALLAX, W('The convex lens must be stronger (shorter focal length) than the concave lens.', 'उत्तल लेंस अवतल लेंस से अधिक प्रबल (कम फ़ोकस दूरी वाला) होना चाहिए।', 'ಪೀನ ಮಸೂರ ನಿಮ್ನ ಮಸೂರಕ್ಕಿಂತ ಹೆಚ್ಚು ಪ್ರಬಲ (ಕಡಿಮೆ ನಾಭಿದೂರ) ಆಗಿರಬೇಕು.')],
        conclusion=W('The combination behaves as one converging lens of focal length F; from it the concave lens has a negative focal length f₂ = F f₁ ÷ (f₁ − F).', 'संयोजन फ़ोकस दूरी F वाले एक अभिसारी लेंस की तरह व्यवहार करता है; उससे अवतल लेंस की फ़ोकस दूरी ऋणात्मक f₂ = F f₁ ÷ (f₁ − F) मिलती है।', 'ಸಂಯೋಜನೆ F ನಾಭಿದೂರದ ಒಂದು ಅಭಿಸರಣ ಮಸೂರದಂತೆ ವರ್ತಿಸುತ್ತದೆ; ಅದರಿಂದ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಋಣ f₂ = F f₁ ÷ (f₁ − F).'),
        viva=[Q(W('Why can’t we find a concave lens’s focal length directly by the u–v method?', 'u–v विधि से सीधे अवतल लेंस की फ़ोकस दूरी क्यों नहीं निकलती?', 'u–v ವಿಧಾನದಿಂದ ನೇರವಾಗಿ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಏಕೆ ಸಿಗುವುದಿಲ್ಲ?'), W('It always forms a virtual image of a real object, which cannot be caught with a needle on the far side.', 'यह वास्तविक वस्तु का सदा आभासी प्रतिबिंब बनाता है, जिसे दूसरी ओर सुई से पकड़ा नहीं जा सकता।', 'ನೈಜ ವಸ್ತುವಿಗೆ ಅದು ಯಾವಾಗಲೂ ಮಿಥ್ಯ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತದೆ; ಅದನ್ನು ಆಚೆ ಸೂಜಿಯಿಂದ ಹಿಡಿಯಲಾಗದು.')),
              Q(W('What is the power of the combination of +10 D and −4 D lenses?', '+10 D और −4 D लेंसों के संयोजन की क्षमता क्या है?', '+10 D ಮತ್ತು −4 D ಮಸೂರಗಳ ಸಂಯೋಜನೆಯ ಸಾಮರ್ಥ್ಯ ಎಷ್ಟು?'), W('+6 D.', '+6 D.', '+6 D.')),
              Q(W('Which lens corrects short sight (myopia)?', 'निकट दृष्टि दोष कौन-सा लेंस ठीक करता है?', 'ಸಮೀಪದೃಷ್ಟಿ ದೋಷವನ್ನು ಯಾವ ಮಸೂರ ಸರಿಪಡಿಸುತ್ತದೆ?'), W('A concave lens.', 'अवतल लेंस।', 'ನಿಮ್ನ ಮಸೂರ.'))])

    lab(id='convex-mirror-focal', bench='convex-mirror', subject='Physics', domain='physics', levels=[12], curricula=['cbse', 'ncert', 'ka-puc'],
        keywords=['ray optics', 'convex mirror', 'focal length', 'radius of curvature'],
        title=W('Focal length of a convex mirror (with a convex lens)', 'उत्तल दर्पण की फ़ोकस दूरी (उत्तल लेंस की सहायता से)', 'ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ (ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ)'),
        summary=W('Use a convex lens to send converging light to the mirror; when the light returns on itself the mirror’s centre of curvature is found.', 'उत्तल लेंस से अभिसारी प्रकाश दर्पण पर भेजें; जब प्रकाश उसी रास्ते लौटे तब दर्पण का वक्रता केंद्र मिल जाता है।', 'ಪೀನ ಮಸೂರದಿಂದ ಅಭಿಸರಣ ಬೆಳಕನ್ನು ದರ್ಪಣಕ್ಕೆ ಕಳುಹಿಸಿ; ಬೆಳಕು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗಿದಾಗ ದರ್ಪಣದ ವಕ್ರತಾ ಕೇಂದ್ರ ಸಿಗುತ್ತದೆ.'),
        aim=W('To find the focal length of a convex mirror using a convex lens.', 'उत्तल लेंस की सहायता से उत्तल दर्पण की फ़ोकस दूरी ज्ञात करना।', 'ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('The lens forms a real image of the needle at P. If the convex mirror is placed so that P is at its centre of curvature, the rays meet the mirror normally, retrace their path, and the image coincides with the needle. Then R = P − M (M is the mirror position) and f = R/2.', 'लेंस सुई का वास्तविक प्रतिबिंब P पर बनाता है। यदि उत्तल दर्पण ऐसे रखा जाए कि P उसका वक्रता केंद्र हो, तो किरणें दर्पण पर अभिलंबवत पड़कर उसी रास्ते लौटती हैं और प्रतिबिंब सुई पर बनता है। तब R = P − M (M दर्पण की स्थिति) और f = R/2.', 'ಮಸೂರ ಸೂಜಿಯ ನೈಜ ಪ್ರತಿಬಿಂಬವನ್ನು P ನಲ್ಲಿ ರೂಪಿಸುತ್ತದೆ. P ಪೀನ ದರ್ಪಣದ ವಕ್ರತಾ ಕೇಂದ್ರವಾಗುವಂತೆ ದರ್ಪಣವನ್ನಿಟ್ಟರೆ ಕಿರಣಗಳು ಲಂಬವಾಗಿ ಬಿದ್ದು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತವೆ; ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯ ಮೇಲೆಯೇ ಮೂಡುತ್ತದೆ. ಆಗ R = P − M (M ದರ್ಪಣದ ಸ್ಥಾನ), f = R/2.'),
        apparatus=[BENCH, W('Convex lens (15 cm)', 'उत्तल लेंस (15 cm)', 'ಪೀನ ಮಸೂರ (15 cm)'), W('Convex mirror', 'उत्तल दर्पण', 'ಪೀನ ದರ್ಪಣ'), NEEDLES],
        steps=[W('Set the object needle and the convex lens so that the lens forms a real image far from it. Find that image point P with the image needle.', 'वस्तु सुई और उत्तल लेंस ऐसे रखें कि लेंस उससे दूर वास्तविक प्रतिबिंब बनाए। प्रतिबिंब सुई से वह बिंदु P ढूँढें।', 'ವಸ್ತು ಸೂಜಿ ಮತ್ತು ಪೀನ ಮಸೂರವನ್ನು ಮಸೂರ ದೂರದಲ್ಲಿ ನೈಜ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸುವಂತೆ ಇಡಿ. ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯಿಂದ ಆ ಬಿಂದು P ಹುಡುಕಿ.'),
               W('Remove the image needle and put the convex mirror between the lens and P, facing the lens.', 'प्रतिबिंब सुई हटाकर उत्तल दर्पण को लेंस और P के बीच, लेंस की ओर मुँह करके रखें।', 'ಪ್ರತಿಬಿಂಬ ಸೂಜಿ ತೆಗೆದು ಪೀನ ದರ್ಪಣವನ್ನು ಮಸೂರ ಮತ್ತು P ನಡುವೆ ಮಸೂರದತ್ತ ಮುಖಮಾಡಿ ಇಡಿ.'),
               W('Move the mirror until the image seen through the lens coincides with the object needle (no parallax). Record its position M.', 'दर्पण तब तक खिसकाएँ जब तक लेंस से दिखता प्रतिबिंब वस्तु सुई से मिल न जाए (लंबन न रहे)। उसकी स्थिति M लिखें।', 'ಮಸೂರದ ಮೂಲಕ ಕಾಣುವ ಪ್ರತಿಬಿಂಬ ವಸ್ತು ಸೂಜಿಯೊಂದಿಗೆ ಸೇರುವವರೆಗೆ (ಭ್ರಂಶ ಇಲ್ಲದೆ) ದರ್ಪಣ ಸರಿಸಿ. ಅದರ ಸ್ಥಾನ M ದಾಖಲಿಸಿ.'),
               W('R = P − M and f = R/2. Repeat with other object distances.', 'R = P − M और f = R/2. दूसरी वस्तु दूरियों के साथ दोहराएँ।', 'R = P − M ಮತ್ತು f = R/2. ಬೇರೆ ವಸ್ತು ದೂರಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[P_ALIGN, P_PARALLAX, W('The real image P must form well beyond the mirror’s focal length from the lens.', 'वास्तविक प्रतिबिंब P लेंस से दर्पण की फ़ोकस दूरी से काफ़ी आगे बनना चाहिए।', 'ನೈಜ ಪ್ರತಿಬಿಂಬ P ಮಸೂರದಿಂದ ದರ್ಪಣದ ನಾಭಿದೂರಕ್ಕಿಂತ ಸಾಕಷ್ಟು ಆಚೆ ಮೂಡಬೇಕು.')],
        conclusion=W('When the mirror is a distance R in front of the lens’s image point the light retraces its path; the convex mirror’s focal length is R/2.', 'जब दर्पण लेंस के प्रतिबिंब बिंदु से R दूरी पहले होता है तो प्रकाश उसी रास्ते लौटता है; उत्तल दर्पण की फ़ोकस दूरी R/2 है।', 'ದರ್ಪಣ ಮಸೂರದ ಪ್ರತಿಬಿಂಬ ಬಿಂದುವಿಗಿಂತ R ದೂರ ಮುಂದೆ ಇದ್ದಾಗ ಬೆಳಕು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತದೆ; ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ R/2.'),
        viva=[Q(W('Why does a convex mirror alone not give a real image?', 'अकेला उत्तल दर्पण वास्तविक प्रतिबिंब क्यों नहीं देता?', 'ಪೀನ ದರ್ಪಣ ಒಂದೇ ನೈಜ ಪ್ರತಿಬಿಂಬ ಏಕೆ ನೀಡುವುದಿಲ್ಲ?'), W('It always diverges the light from a real object.', 'यह वास्तविक वस्तु के प्रकाश को सदा अपसारित करता है।', 'ನೈಜ ವಸ್ತುವಿನ ಬೆಳಕನ್ನು ಅದು ಯಾವಾಗಲೂ ಅಪಸರಿಸುತ್ತದೆ.')),
              Q(W('When does a ray retrace its path after reflection?', 'परावर्तन के बाद किरण कब उसी रास्ते लौटती है?', 'ಪ್ರತಿಫಲನದ ನಂತರ ಕಿರಣ ಯಾವಾಗ ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತದೆ?'), W('When it falls normally on the mirror, along a radius.', 'जब वह दर्पण पर अभिलंबवत, त्रिज्या के अनुदिश पड़ती है।', 'ಅದು ದರ್ಪಣದ ಮೇಲೆ ಲಂಬವಾಗಿ, ತ್ರಿಜ್ಯದ ಉದ್ದಕ್ಕೂ ಬಿದ್ದಾಗ.')),
              Q(W('Give a use of a convex mirror.', 'उत्तल दर्पण का एक उपयोग बताइए।', 'ಪೀನ ದರ್ಪಣದ ಒಂದು ಉಪಯೋಗ ತಿಳಿಸಿ.'), W('Rear-view mirrors and shop security mirrors.', 'पीछे देखने वाले दर्पण और दुकानों के सुरक्षा दर्पण।', 'ಹಿಂಬದಿ ನೋಟದ ದರ್ಪಣಗಳು ಮತ್ತು ಅಂಗಡಿ ಭದ್ರತಾ ದರ್ಪಣಗಳು.'))])

    lab(id='refractive-index-microscope', bench='travelling-microscope', subject='Physics', domain='physics', levels=[12], curricula=['cbse', 'ncert', 'ka-puc'],
        keywords=['refractive index', 'travelling microscope', 'real depth', 'apparent depth', 'glass slab', 'refraction'],
        title=W('Refractive index of a glass slab (travelling microscope)', 'काँच के गुटके का अपवर्तनांक (चल सूक्ष्मदर्शी)', 'ಗಾಜಿನ ಚಪ್ಪಡಿಯ ವಕ್ರೀಭವನಾಂಕ (ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ)'),
        summary=W('Focus a microscope on a mark, on the mark seen through a slab, and on the top of the slab; real ÷ apparent depth gives n.', 'सूक्ष्मदर्शी को एक निशान पर, गुटके से दिखते निशान पर और गुटके के ऊपरी तल पर फ़ोकस करें; वास्तविक ÷ आभासी गहराई से n मिलता है।', 'ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಗುರುತಿನ ಮೇಲೆ, ಚಪ್ಪಡಿಯ ಮೂಲಕ ಕಾಣುವ ಗುರುತಿನ ಮೇಲೆ ಮತ್ತು ಚಪ್ಪಡಿಯ ಮೇಲ್ಮೈ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ; ನೈಜ ÷ ತೋರಿಕೆಯ ಆಳ n ನೀಡುತ್ತದೆ.'),
        aim=W('To find the refractive index of a glass slab using a travelling microscope.', 'चल सूक्ष्मदर्शी से काँच के गुटके का अपवर्तनांक ज्ञात करना।', 'ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕದಿಂದ ಗಾಜಿನ ಚಪ್ಪಡಿಯ ವಕ್ರೀಭವನಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Light from a mark under a slab bends away from the normal as it leaves the glass, so the mark seems raised. For near-normal viewing, n = real depth ÷ apparent depth = (R₃ − R₁) ÷ (R₃ − R₂), where R₁, R₂, R₃ are the microscope readings for the mark, the mark through the slab and the top of the slab.', 'गुटके के नीचे के निशान का प्रकाश काँच से निकलते समय अभिलंब से दूर मुड़ता है, इसलिए निशान ऊपर उठा दिखता है। लगभग अभिलंब दिशा से देखने पर n = वास्तविक गहराई ÷ आभासी गहराई = (R₃ − R₁) ÷ (R₃ − R₂), जहाँ R₁, R₂, R₃ निशान, गुटके से दिखते निशान और गुटके के ऊपरी तल के सूक्ष्मदर्शी पाठ्यांक हैं।', 'ಚಪ್ಪಡಿಯ ಕೆಳಗಿನ ಗುರುತಿನ ಬೆಳಕು ಗಾಜಿನಿಂದ ಹೊರಬರುವಾಗ ಲಂಬದಿಂದ ದೂರ ಬಾಗುತ್ತದೆ; ಆದ್ದರಿಂದ ಗುರುತು ಮೇಲೆದ್ದಂತೆ ಕಾಣುತ್ತದೆ. ಸುಮಾರು ಲಂಬವಾಗಿ ನೋಡಿದಾಗ n = ನೈಜ ಆಳ ÷ ತೋರಿಕೆಯ ಆಳ = (R₃ − R₁) ÷ (R₃ − R₂); R₁, R₂, R₃ ಗುರುತು, ಚಪ್ಪಡಿಯ ಮೂಲಕ ಗುರುತು ಮತ್ತು ಚಪ್ಪಡಿಯ ಮೇಲ್ಮೈಗೆ ಸೂಕ್ಷ್ಮದರ್ಶಕದ ಓದುಗಳು.'),
        apparatus=[W('Travelling microscope (least count 0.001 cm)', 'चल सूक्ष्मदर्शी (अल्पतमांक 0.001 cm)', 'ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ (ಕನಿಷ್ಠ ಎಣಿಕೆ 0.001 cm)'), W('Glass slab', 'काँच का गुटका', 'ಗಾಜಿನ ಚಪ್ಪಡಿ'), W('Paper with an ink cross', 'स्याही के क्रॉस वाला कागज़', 'ಶಾಯಿ ಅಡ್ಡಗುರುತಿನ ಕಾಗದ'), W('Lycopodium powder', 'लाइकोपोडियम चूर्ण', 'ಲೈಕೋಪೋಡಿಯಂ ಪುಡಿ')],
        steps=[W('Focus the microscope on the ink cross and note the reading R₁.', 'सूक्ष्मदर्शी को स्याही के क्रॉस पर फ़ोकस करें और पाठ्यांक R₁ लिखें।', 'ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಶಾಯಿ ಅಡ್ಡಗುರುತಿನ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ R₁ ಓದನ್ನು ಬರೆಯಿರಿ.'),
               W('Place the slab over the cross. Raise the microscope until the cross is sharp again: reading R₂.', 'क्रॉस पर गुटका रखें। सूक्ष्मदर्शी को तब तक ऊपर उठाएँ जब तक क्रॉस फिर स्पष्ट न हो: पाठ्यांक R₂.', 'ಅಡ್ಡಗುರುತಿನ ಮೇಲೆ ಚಪ್ಪಡಿ ಇಡಿ. ಅಡ್ಡಗುರುತು ಮತ್ತೆ ಸ್ಪಷ್ಟವಾಗುವವರೆಗೆ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಮೇಲೆತ್ತಿ: ಓದು R₂.'),
               W('Sprinkle a little powder on top of the slab and focus on it: reading R₃.', 'गुटके के ऊपर थोड़ा चूर्ण छिड़ककर उस पर फ़ोकस करें: पाठ्यांक R₃.', 'ಚಪ್ಪಡಿಯ ಮೇಲೆ ಸ್ವಲ್ಪ ಪುಡಿ ಚಿಮುಕಿಸಿ ಅದರ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ: ಓದು R₃.'),
               W('Work out n = (R₃ − R₁) ÷ (R₃ − R₂).', 'n = (R₃ − R₁) ÷ (R₃ − R₂) निकालें।', 'n = (R₃ − R₁) ÷ (R₃ − R₂) ಲೆಕ್ಕಿಸಿ.'),
               W('Repeat with slabs of other thickness or glass.', 'दूसरी मोटाई या काँच के गुटकों के साथ दोहराएँ।', 'ಬೇರೆ ದಪ್ಪ ಅಥವಾ ಗಾಜಿನ ಚಪ್ಪಡಿಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Move the microscope in one direction only, to avoid backlash error.', 'पश्च-गति त्रुटि से बचने के लिए सूक्ष्मदर्शी को केवल एक दिशा में चलाएँ।', 'ಹಿಂಚಲನೆ ದೋಷ ತಪ್ಪಿಸಲು ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಸರಿಸಿ.'), P_ZERO,
                     W('Use only a thin layer of powder.', 'चूर्ण की केवल पतली परत लें।', 'ಪುಡಿಯ ತೆಳು ಪದರ ಮಾತ್ರ ಬಳಸಿ.')],
        conclusion=W('The mark appears raised by t(1 − 1/n), and real ÷ apparent depth gives the refractive index of the glass (about 1.5).', 'निशान t(1 − 1/n) ऊपर उठा दिखता है, और वास्तविक ÷ आभासी गहराई से काँच का अपवर्तनांक (लगभग 1.5) मिलता है।', 'ಗುರುತು t(1 − 1/n) ಮೇಲೆದ್ದಂತೆ ಕಾಣುತ್ತದೆ; ನೈಜ ÷ ತೋರಿಕೆಯ ಆಳ ಗಾಜಿನ ವಕ್ರೀಭವನಾಂಕ (ಸುಮಾರು 1.5) ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why does a pond look shallower than it is?', 'तालाब वास्तविकता से उथला क्यों दिखता है?', 'ಕೊಳ ನಿಜಕ್ಕಿಂತ ಆಳ ಕಡಿಮೆ ಏಕೆ ಕಾಣುತ್ತದೆ?'), W('Refraction at the water surface: the apparent depth is the real depth ÷ n.', 'पानी की सतह पर अपवर्तन: आभासी गहराई = वास्तविक गहराई ÷ n.', 'ನೀರಿನ ಮೇಲ್ಮೈಯಲ್ಲಿ ವಕ್ರೀಭವನ: ತೋರಿಕೆಯ ಆಳ = ನೈಜ ಆಳ ÷ n.')),
              Q(W('What is the least count of a travelling microscope?', 'चल सूक्ष्मदर्शी का अल्पतमांक क्या है?', 'ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕದ ಕನಿಷ್ಠ ಎಣಿಕೆ ಎಷ್ಟು?'), W('Usually 0.001 cm (one main-scale division ÷ number of vernier divisions).', 'प्रायः 0.001 cm (मुख्य पैमाने का एक भाग ÷ वर्नियर भागों की संख्या)।', 'ಸಾಮಾನ್ಯವಾಗಿ 0.001 cm (ಮುಖ್ಯ ಅಳತೆಯ ಒಂದು ಭಾಗ ÷ ವರ್ನಿಯರ್ ಭಾಗಗಳ ಸಂಖ್ಯೆ).')),
              Q(W('Does n depend on the colour of light?', 'क्या n प्रकाश के रंग पर निर्भर करता है?', 'n ಬೆಳಕಿನ ಬಣ್ಣವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?'), W('Yes: it is larger for violet than for red (dispersion).', 'हाँ: बैंगनी के लिए लाल से अधिक होता है (वर्ण विक्षेपण)।', 'ಹೌದು: ನೇರಳೆಗೆ ಕೆಂಪಿಗಿಂತ ಹೆಚ್ಚು (ವರ್ಣ ವಿಕ್ಷೇಪಣ).'))])

    lab(id='diffraction-grating', bench='grating', subject='Physics', domain='physics', levels=['ug'], curricula=['ug-physics'],
        keywords=['diffraction grating', 'grating', 'spectrometer', 'wavelength', 'mercury spectrum', 'diffraction', 'wave optics'],
        title=W('Wavelengths of spectral lines with a diffraction grating', 'विवर्तन ग्रेटिंग से स्पेक्ट्रमी रेखाओं की तरंगदैर्घ्य', 'ವಿವರ್ತನ ಗ್ರೇಟಿಂಗ್‌ನಿಂದ ರೋಹಿತ ರೇಖೆಗಳ ತರಂಗಾಂತರ'),
        summary=W('Measure the diffraction angles of mercury lines with a spectrometer and compute λ = d sin θ / n.', 'स्पेक्ट्रोमीटर से पारे की रेखाओं के विवर्तन कोण मापें और λ = d sin θ / n निकालें।', 'ರೋಹಿತಮಾಪಕದಿಂದ ಪಾದರಸ ರೇಖೆಗಳ ವಿವರ್ತನ ಕೋನಗಳನ್ನು ಅಳೆದು λ = d sin θ / n ಲೆಕ್ಕಿಸಿ.'),
        aim=W('To find the wavelengths of the prominent lines of mercury using a plane transmission grating.', 'समतल पारगमन ग्रेटिंग से पारे की प्रमुख रेखाओं की तरंगदैर्घ्य ज्ञात करना।', 'ಸಮತಲ ಪ್ರಸರಣ ಗ್ರೇಟಿಂಗ್ ಬಳಸಿ ಪಾದರಸದ ಪ್ರಮುಖ ರೇಖೆಗಳ ತರಂಗಾಂತರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A grating with N lines per metre has spacing d = 1/N. Light from the slits reinforces where the path difference is a whole number of wavelengths: d sin θ = nλ. Measuring θ for each line and order gives λ.', 'प्रति मीटर N रेखाओं वाली ग्रेटिंग का अंतराल d = 1/N है। झिरियों का प्रकाश वहाँ प्रबल होता है जहाँ पथांतर तरंगदैर्घ्य का पूर्ण गुणज हो: d sin θ = nλ. हर रेखा और कोटि के लिए θ मापकर λ मिलती है।', 'ಪ್ರತಿ ಮೀಟರ್‌ಗೆ N ರೇಖೆಗಳ ಗ್ರೇಟಿಂಗ್‌ನ ಅಂತರ d = 1/N. ಪಥಾಂತರ ತರಂಗಾಂತರದ ಪೂರ್ಣ ಗುಣಕವಾದಲ್ಲಿ ಸೀಳುಗಳ ಬೆಳಕು ಬಲಗೊಳ್ಳುತ್ತದೆ: d sin θ = nλ. ಪ್ರತಿ ರೇಖೆ ಮತ್ತು ಕ್ರಮಕ್ಕೆ θ ಅಳೆದು λ ಪಡೆಯಬಹುದು.'),
        apparatus=[W('Spectrometer', 'स्पेक्ट्रोमीटर', 'ರೋಹಿತಮಾಪಕ'), W('Plane transmission grating (300–600 lines/mm)', 'समतल पारगमन ग्रेटिंग (300–600 रेखाएँ/mm)', 'ಸಮತಲ ಪ್ರಸರಣ ಗ್ರೇಟಿಂಗ್ (300–600 ರೇಖೆ/mm)'), W('Mercury vapour lamp', 'पारद वाष्प लैंप', 'ಪಾದರಸ ಆವಿ ದೀಪ'), W('Spirit level and reading lens', 'स्पिरिट लेवल और पठन लेंस', 'ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಮತ್ತು ಓದುವ ಮಸೂರ')],
        steps=[W('Level the spectrometer and focus the telescope and collimator for parallel light (Schuster’s method).', 'स्पेक्ट्रोमीटर को समतल करें और समांतर प्रकाश के लिए दूरदर्शी तथा समांतरित्र फ़ोकस करें (शुस्टर विधि)।', 'ರೋಹಿತಮಾಪಕವನ್ನು ಸಮತಲಗೊಳಿಸಿ, ಸಮಾಂತರ ಬೆಳಕಿಗಾಗಿ ದೂರದರ್ಶಕ ಮತ್ತು ಸಮಾಂತರಕವನ್ನು ಕೇಂದ್ರೀಕರಿಸಿ (ಶುಸ್ಟರ್ ವಿಧಾನ).'),
               W('Set the grating normal to the incident light.', 'ग्रेटिंग को आपतित प्रकाश के अभिलंब रखें।', 'ಗ್ರೇಟಿಂಗನ್ನು ಆಪಾತ ಬೆಳಕಿಗೆ ಲಂಬವಾಗಿಡಿ.'),
               W('Turn the telescope to each coloured line of the first order on one side and set the cross-wire on it; read the angle.', 'दूरदर्शी को एक ओर प्रथम कोटि की हर रंगीन रेखा पर घुमाकर क्रॉस-तार उस पर रखें; कोण पढ़ें।', 'ದೂರದರ್ಶಕವನ್ನು ಒಂದು ಕಡೆ ಮೊದಲ ಕ್ರಮದ ಪ್ರತಿ ಬಣ್ಣದ ರೇಖೆಗೆ ತಿರುಗಿಸಿ ಅಡ್ಡತಂತಿಯನ್ನು ಅದರ ಮೇಲಿಡಿ; ಕೋನ ಓದಿ.'),
               W('Repeat on the other side and for the second order; take θ as half the angle between the two sides.', 'दूसरी ओर और द्वितीय कोटि के लिए दोहराएँ; θ को दोनों ओर के कोणों के अंतर का आधा लें।', 'ಇನ್ನೊಂದು ಕಡೆ ಮತ್ತು ಎರಡನೇ ಕ್ರಮಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; θ ಅನ್ನು ಎರಡು ಕಡೆಗಳ ಕೋನ ವ್ಯತ್ಯಾಸದ ಅರ್ಧವಾಗಿ ತೆಗೆದುಕೊಳ್ಳಿ.'),
               W('Work out λ = d sin θ / n for each line and its uncertainty.', 'हर रेखा के लिए λ = d sin θ / n और उसकी अनिश्चितता निकालें।', 'ಪ್ರತಿ ರೇಖೆಗೆ λ = d sin θ / n ಮತ್ತು ಅದರ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ.'), CSV],
        precautions=[W('Never touch the ruled surface of the grating.', 'ग्रेटिंग की रेखित सतह को कभी न छुएँ।', 'ಗ್ರೇಟಿಂಗ್‌ನ ಗೆರೆಹಾಕಿದ ಮೇಲ್ಮೈಯನ್ನು ಎಂದೂ ಮುಟ್ಟಬೇಡಿ.'), W('Read both verniers to cancel eccentricity error.', 'उत्केंद्रता त्रुटि मिटाने के लिए दोनों वर्नियर पढ़ें।', 'ಉತ್ಕೇಂದ್ರತೆ ದೋಷ ರದ್ದುಗೊಳಿಸಲು ಎರಡೂ ವರ್ನಿಯರ್ ಓದಿ.'),
                     W('Do not look at the mercury lamp directly; it gives out ultraviolet light.', 'पारद लैंप को सीधे न देखें; यह पराबैंगनी प्रकाश देता है।', 'ಪಾದರಸ ದೀಪವನ್ನು ನೇರವಾಗಿ ನೋಡಬೇಡಿ; ಅದು ಅತಿನೇರಳೆ ಬೆಳಕು ನೀಡುತ್ತದೆ.')],
        conclusion=W('The wavelengths of the violet, blue, green and yellow mercury lines agree with the standard values (404.7, 435.8, 546.1 and about 578 nm) within the uncertainty.', 'पारे की बैंगनी, नीली, हरी और पीली रेखाओं की तरंगदैर्घ्य अनिश्चितता के भीतर मानक मानों (404.7, 435.8, 546.1 और लगभग 578 nm) से मेल खाती हैं।', 'ಪಾದರಸದ ನೇರಳೆ, ನೀಲಿ, ಹಸಿರು ಮತ್ತು ಹಳದಿ ರೇಖೆಗಳ ತರಂಗಾಂತರಗಳು ಅನಿಶ್ಚಿತತೆಯೊಳಗೆ ಪ್ರಮಾಣಿತ ಮೌಲ್ಯಗಳಿಗೆ (404.7, 435.8, 546.1 ಮತ್ತು ಸುಮಾರು 578 nm) ಹೊಂದುತ್ತವೆ.'),
        viva=[Q(W('Why do higher orders spread the spectrum more?', 'उच्च कोटियाँ स्पेक्ट्रम को अधिक क्यों फैलाती हैं?', 'ಹೆಚ್ಚಿನ ಕ್ರಮಗಳು ರೋಹಿತವನ್ನು ಹೆಚ್ಚು ಏಕೆ ಹರಡುತ್ತವೆ?'), W('Dispersion dθ/dλ = n/(d cos θ) grows with the order n.', 'वर्ण विक्षेपण dθ/dλ = n/(d cos θ) कोटि n के साथ बढ़ता है।', 'ವಿಕ್ಷೇಪಣ dθ/dλ = n/(d cos θ) ಕ್ರಮ n ನೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ.')),
              Q(W('What limits the highest order you can see?', 'दिखने वाली सबसे ऊँची कोटि किससे सीमित होती है?', 'ಕಾಣುವ ಗರಿಷ್ಠ ಕ್ರಮವನ್ನು ಯಾವುದು ಮಿತಿಗೊಳಿಸುತ್ತದೆ?'), W('sin θ cannot exceed 1, so n ≤ d/λ.', 'sin θ, 1 से अधिक नहीं हो सकता, इसलिए n ≤ d/λ.', 'sin θ 1 ಮೀರಲಾರದು, ಆದ್ದರಿಂದ n ≤ d/λ.')),
              Q(W('How is a grating spectrum different from a prism spectrum?', 'ग्रेटिंग स्पेक्ट्रम प्रिज़्म स्पेक्ट्रम से कैसे भिन्न है?', 'ಗ್ರೇಟಿಂಗ್ ರೋಹಿತ ಪಟ್ಟಕ ರೋಹಿತಕ್ಕಿಂತ ಹೇಗೆ ಭಿನ್ನ?'), W('Red is deviated most in a grating, least in a prism; the grating spectrum is nearly linear in λ.', 'ग्रेटिंग में लाल सबसे अधिक, प्रिज़्म में सबसे कम विचलित होता है; ग्रेटिंग स्पेक्ट्रम λ में लगभग रैखिक है।', 'ಗ್ರೇಟಿಂಗ್‌ನಲ್ಲಿ ಕೆಂಪು ಅತಿ ಹೆಚ್ಚು, ಪಟ್ಟಕದಲ್ಲಿ ಅತಿ ಕಡಿಮೆ ವಿಚಲಿಸುತ್ತದೆ; ಗ್ರೇಟಿಂಗ್ ರೋಹಿತ λ ಯಲ್ಲಿ ಬಹುತೇಕ ರೇಖೀಯ.'))])

    lab(id='newtons-rings', bench='newton-rings', subject='Physics', domain='physics', levels=['ug'], curricula=['ug-physics'],
        keywords=["newton's rings", 'interference', 'thin film', 'wavelength', 'sodium light', 'wave optics'],
        title=W("Wavelength of sodium light by Newton's rings", 'न्यूटन के वलयों से सोडियम प्रकाश की तरंगदैर्घ्य', 'ನ್ಯೂಟನ್ ಉಂಗುರಗಳಿಂದ ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರ'),
        summary=W('Measure the diameters of dark rings under a lens; the slope of D² against n gives λ.', 'लेंस के नीचे काले वलयों के व्यास मापें; D² और n के ग्राफ़ की प्रवणता से λ मिलती है।', 'ಮಸೂರದ ಕೆಳಗಿನ ಕಪ್ಪು ಉಂಗುರಗಳ ವ್ಯಾಸ ಅಳೆಯಿರಿ; D² ಮತ್ತು n ನಕ್ಷೆಯ ಇಳಿಜಾರು λ ನೀಡುತ್ತದೆ.'),
        aim=W("To find the wavelength of sodium light using Newton's rings.", 'न्यूटन के वलयों से सोडियम प्रकाश की तरंगदैर्घ्य ज्ञात करना।', 'ನ್ಯೂಟನ್ ಉಂಗುರಗಳಿಂದ ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A thin air film between a plano-convex lens and a glass plate gets thicker away from the centre. Light reflected from its two surfaces interferes; with the extra half-wave on reflection the centre is dark and the nth dark ring has Dₙ² = 4nλR. So the slope of D² against n is 4λR.', 'समतल-उत्तल लेंस और काँच की प्लेट के बीच वायु की पतली परत केंद्र से दूर मोटी होती जाती है। उसकी दोनों सतहों से परावर्तित प्रकाश व्यतिकरण करता है; परावर्तन पर अतिरिक्त अर्ध-तरंग के कारण केंद्र काला होता है और n वें काले वलय के लिए Dₙ² = 4nλR. अतः D² और n की प्रवणता 4λR है।', 'ಸಮತಲ-ಪೀನ ಮಸೂರ ಮತ್ತು ಗಾಜಿನ ತಟ್ಟೆಯ ನಡುವಿನ ತೆಳು ಗಾಳಿ ಪದರ ಕೇಂದ್ರದಿಂದ ದೂರ ಹೋದಂತೆ ದಪ್ಪವಾಗುತ್ತದೆ. ಅದರ ಎರಡು ಮೇಲ್ಮೈಗಳಿಂದ ಪ್ರತಿಫಲಿಸಿದ ಬೆಳಕು ವ್ಯತಿಕರಣಗೊಳ್ಳುತ್ತದೆ; ಪ್ರತಿಫಲನದ ಹೆಚ್ಚುವರಿ ಅರ್ಧ-ತರಂಗದಿಂದ ಕೇಂದ್ರ ಕಪ್ಪು; n ನೇ ಕಪ್ಪು ಉಂಗುರಕ್ಕೆ Dₙ² = 4nλR. ಆದ್ದರಿಂದ D² ಮತ್ತು n ಇಳಿಜಾರು 4λR.'),
        apparatus=[W("Newton's rings apparatus (plano-convex lens on a glass plate)", 'न्यूटन वलय उपकरण (काँच की प्लेट पर समतल-उत्तल लेंस)', 'ನ್ಯೂಟನ್ ಉಂಗುರ ಉಪಕರಣ (ಗಾಜಿನ ತಟ್ಟೆಯ ಮೇಲೆ ಸಮತಲ-ಪೀನ ಮಸೂರ)'), W('Sodium vapour lamp', 'सोडियम वाष्प लैंप', 'ಸೋಡಿಯಂ ಆವಿ ದೀಪ'), W('Travelling microscope', 'चल सूक्ष्मदर्शी', 'ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ'), W('Glass plate at 45°', '45° पर काँच की प्लेट', '45° ನಲ್ಲಿ ಗಾಜಿನ ತಟ್ಟೆ')],
        steps=[W('Send sodium light down onto the lens with the 45° glass plate and focus the microscope on the rings.', '45° काँच की प्लेट से सोडियम प्रकाश लेंस पर नीचे भेजें और सूक्ष्मदर्शी को वलयों पर फ़ोकस करें।', '45° ಗಾಜಿನ ತಟ್ಟೆಯಿಂದ ಸೋಡಿಯಂ ಬೆಳಕನ್ನು ಮಸೂರದ ಮೇಲೆ ಕೆಳಗೆ ಕಳುಹಿಸಿ, ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಉಂಗುರಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ.'),
               W('Set the cross-wire at the dark centre, then move out to the 20th dark ring.', 'क्रॉस-तार को काले केंद्र पर रखें, फिर 20वें काले वलय तक बाहर जाएँ।', 'ಅಡ್ಡತಂತಿಯನ್ನು ಕಪ್ಪು ಕೇಂದ್ರದಲ್ಲಿಟ್ಟು, ನಂತರ 20ನೇ ಕಪ್ಪು ಉಂಗುರದವರೆಗೆ ಹೊರಗೆ ಸರಿಯಿರಿ.'),
               W('Come back, reading the microscope at every fourth dark ring on one side, then across the centre on the other side.', 'वापस आते हुए एक ओर हर चौथे काले वलय पर, फिर केंद्र पार दूसरी ओर, सूक्ष्मदर्शी पढ़ें।', 'ಹಿಂತಿರುಗುವಾಗ ಒಂದು ಕಡೆ ಪ್ರತಿ ನಾಲ್ಕನೇ ಕಪ್ಪು ಉಂಗುರದಲ್ಲಿ, ನಂತರ ಕೇಂದ್ರದ ಆಚೆ ಇನ್ನೊಂದು ಕಡೆ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಓದಿ.'),
               W('Find each diameter Dₙ and plot Dₙ² against n.', 'हर व्यास Dₙ ज्ञात करके Dₙ² और n का ग्राफ़ बनाएँ।', 'ಪ್ರತಿ ವ್ಯಾಸ Dₙ ಕಂಡುಹಿಡಿದು Dₙ² ಮತ್ತು n ನಕ್ಷೆ ಎಳೆಯಿರಿ.'),
               W('Find R with a spherometer and work out λ = slope ÷ 4R with its uncertainty.', 'गोलाईमापी से R ज्ञात करें और λ = प्रवणता ÷ 4R उसकी अनिश्चितता सहित निकालें।', 'ಗೋಳಮಾಪಕದಿಂದ R ಕಂಡುಹಿಡಿದು λ = ಇಳಿಜಾರು ÷ 4R ಅನಿಶ್ಚಿತತೆ ಸಹಿತ ಲೆಕ್ಕಿಸಿ.'), CSV],
        precautions=[W('Move the microscope in one direction only (no backlash).', 'सूक्ष्मदर्शी को केवल एक दिशा में चलाएँ (पश्च-गति नहीं)।', 'ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಸರಿಸಿ (ಹಿಂಚಲನೆ ಇಲ್ಲ).'), W('Count the rings carefully; do not skip one.', 'वलय ध्यान से गिनें; कोई न छोड़ें।', 'ಉಂಗುರಗಳನ್ನು ಎಚ್ಚರದಿಂದ ಎಣಿಸಿ; ಯಾವುದನ್ನೂ ಬಿಡಬೇಡಿ.'),
                     W('Clean the lens and plate so the centre is dark.', 'लेंस और प्लेट साफ़ करें ताकि केंद्र काला रहे।', 'ಕೇಂದ್ರ ಕಪ್ಪಾಗಿರುವಂತೆ ಮಸೂರ ಮತ್ತು ತಟ್ಟೆ ಸ್ವಚ್ಛಗೊಳಿಸಿ.')],
        conclusion=W('Dₙ² rises in a straight line with n, and the slope gives the wavelength of sodium light close to 589 nm.', 'Dₙ², n के साथ सीधी रेखा में बढ़ता है, और प्रवणता से सोडियम प्रकाश की तरंगदैर्घ्य 589 nm के निकट मिलती है।', 'Dₙ², n ಯೊಂದಿಗೆ ಸರಳರೇಖೆಯಲ್ಲಿ ಏರುತ್ತದೆ; ಇಳಿಜಾರು ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರವನ್ನು 589 nm ಹತ್ತಿರ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why is the centre dark in reflected light?', 'परावर्तित प्रकाश में केंद्र काला क्यों होता है?', 'ಪ್ರತಿಫಲಿತ ಬೆಳಕಿನಲ್ಲಿ ಕೇಂದ್ರ ಏಕೆ ಕಪ್ಪು?'), W('The film thickness is zero there, and reflection at the denser glass adds a phase change of π.', 'वहाँ परत की मोटाई शून्य है, और सघन काँच पर परावर्तन से π का कलांतर जुड़ता है।', 'ಅಲ್ಲಿ ಪದರದ ದಪ್ಪ ಶೂನ್ಯ; ಸಾಂದ್ರ ಗಾಜಿನ ಮೇಲಿನ ಪ್ರತಿಫಲನ π ಹಂತ ಬದಲಾವಣೆ ಸೇರಿಸುತ್ತದೆ.')),
              Q(W('Why do the rings get closer together further out?', 'बाहर की ओर वलय पास-पास क्यों हो जाते हैं?', 'ಹೊರಗೆ ಹೋದಂತೆ ಉಂಗುರಗಳು ಏಕೆ ಹತ್ತಿರವಾಗುತ್ತವೆ?'), W('The radius goes as √n, so successive rings differ less in radius.', 'त्रिज्या √n के अनुसार बढ़ती है, इसलिए क्रमागत वलयों की त्रिज्या में अंतर घटता है।', 'ತ್ರಿಜ್ಯ √n ನಂತೆ ಬೆಳೆಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಅನುಕ್ರಮ ಉಂಗುರಗಳ ತ್ರಿಜ್ಯ ವ್ಯತ್ಯಾಸ ಕಡಿಮೆ.')),
              Q(W('What happens if water fills the gap?', 'यदि अंतराल में पानी भर दें तो क्या होगा?', 'ಅಂತರದಲ್ಲಿ ನೀರು ತುಂಬಿದರೆ ಏನಾಗುತ್ತದೆ?'), W('The rings shrink: D² is divided by the refractive index of water.', 'वलय छोटे हो जाते हैं: D² पानी के अपवर्तनांक से विभाजित हो जाता है।', 'ಉಂಗುರಗಳು ಕುಗ್ಗುತ್ತವೆ: D², ನೀರಿನ ವಕ್ರೀಭವನಾಂಕದಿಂದ ಭಾಗಿಸಲ್ಪಡುತ್ತದೆ.'))])

    # ---------------------------------------------------------- mechanics
    mech = dict(subject='Physics', domain='physics', curricula=['cbse', 'ncert', 'ka-puc'])
    lab(id='hookes-law', bench='spring', levels=[11], **mech,
        keywords=["hooke's law", 'spring', 'spring constant', 'elasticity', 'mechanical properties of solids', 'extension'],
        title=W("Hooke's law with a helical spring", 'कुंडलित स्प्रिंग से हुक का नियम', 'ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್‌ನಿಂದ ಹುಕ್‌ನ ನಿಯಮ'),
        summary=W('Hang weights on a spring, read the pointer, and find the spring constant from the load–extension graph.', 'स्प्रिंग पर बाट लटकाएँ, सूचक पढ़ें, और भार–विस्तार ग्राफ़ से स्प्रिंग नियतांक ज्ञात करें।', 'ಸ್ಪ್ರಿಂಗ್‌ಗೆ ತೂಕಗಳನ್ನು ತೂಗುಹಾಕಿ, ಸೂಚಕ ಓದಿ, ಭಾರ–ವಿಸ್ತರಣೆ ನಕ್ಷೆಯಿಂದ ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the force constant of a helical spring by plotting a graph between load and extension.', 'भार और विस्तार के बीच ग्राफ़ बनाकर कुंडलित स्प्रिंग का बल नियतांक ज्ञात करना।', 'ಭಾರ ಮತ್ತು ವಿಸ್ತರಣೆಯ ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್‌ನ ಬಲ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W("Within the elastic limit the extension of a spring is proportional to the stretching force: F = kx (Hooke's law). The graph of extension against force is a straight line through the origin of slope 1/k.", 'प्रत्यास्थता सीमा के भीतर स्प्रिंग का विस्तार खींचने वाले बल के अनुक्रमानुपाती है: F = kx (हुक का नियम)। विस्तार और बल का ग्राफ़ मूल बिंदु से जाने वाली 1/k प्रवणता की सीधी रेखा है।', 'ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ಸ್ಪ್ರಿಂಗ್‌ನ ವಿಸ್ತರಣೆ ಎಳೆಯುವ ಬಲಕ್ಕೆ ಅನುಪಾತೀಯ: F = kx (ಹುಕ್ ನಿಯಮ). ವಿಸ್ತರಣೆ ಮತ್ತು ಬಲದ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ 1/k ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ.'),
        apparatus=[W('Helical spring with pointer', 'सूचक सहित कुंडलित स्प्रिंग', 'ಸೂಚಕ ಸಹಿತ ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್'), STAND, WEIGHTS, SCALE],
        steps=[W('Hang the spring from the stand with the hanger and note the pointer reading with no extra load.', 'स्टैंड से स्प्रिंग और हैंगर लटकाएँ और बिना अतिरिक्त भार के सूचक का पाठ्यांक लिखें।', 'ಸ್ಟ್ಯಾಂಡ್‌ನಿಂದ ಸ್ಪ್ರಿಂಗ್ ಮತ್ತು ಹ್ಯಾಂಗರ್ ತೂಗುಹಾಕಿ, ಹೆಚ್ಚುವರಿ ಭಾರವಿಲ್ಲದೆ ಸೂಚಕದ ಓದನ್ನು ಬರೆಯಿರಿ.'),
               W('Add 50 g at a time, waiting for the pointer to settle, and record each reading.', 'एक बार में 50 g जोड़ें, सूचक के स्थिर होने की प्रतीक्षा करें, और हर पाठ्यांक लिखें।', 'ಒಮ್ಮೆಗೆ 50 g ಸೇರಿಸಿ, ಸೂಚಕ ಸ್ಥಿರವಾಗುವವರೆಗೆ ಕಾದು, ಪ್ರತಿ ಓದು ದಾಖಲಿಸಿ.'),
               W('Remove the loads one by one and read again (loading and unloading should agree).', 'भार एक-एक करके हटाएँ और फिर पढ़ें (भार बढ़ाते और घटाते समय पाठ्यांक मेल खाने चाहिए)।', 'ಭಾರಗಳನ್ನು ಒಂದೊಂದಾಗಿ ತೆಗೆದು ಮತ್ತೆ ಓದಿ (ಹೆಚ್ಚಿಸುವ ಮತ್ತು ಇಳಿಸುವ ಓದುಗಳು ಹೊಂದಬೇಕು).'),
               W('Plot extension against force (F = mg) and find k from the slope.', 'विस्तार और बल (F = mg) का ग्राफ़ बनाएँ और प्रवणता से k ज्ञात करें।', 'ವಿಸ್ತರಣೆ ಮತ್ತು ಬಲ (F = mg) ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರಿನಿಂದ k ಕಂಡುಹಿಡಿಯಿರಿ.')],
        precautions=[W('Do not load the spring beyond its elastic limit.', 'स्प्रिंग पर प्रत्यास्थता सीमा से अधिक भार न डालें।', 'ಸ್ಪ್ರಿಂಗ್‌ಗೆ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿ ಮೀರಿ ಭಾರ ಹಾಕಬೇಡಿ.'), W('Read the pointer with your eye level with it.', 'सूचक को आँख उसकी सीध में रखकर पढ़ें।', 'ಸೂಚಕವನ್ನು ಕಣ್ಣು ಅದರ ಮಟ್ಟದಲ್ಲಿಟ್ಟು ಓದಿ.'), W('Add the weights gently so the spring does not swing.', 'बाट धीरे से जोड़ें ताकि स्प्रिंग न झूले।', 'ಸ್ಪ್ರಿಂಗ್ ತೂಗಾಡದಂತೆ ತೂಕಗಳನ್ನು ನಿಧಾನವಾಗಿ ಸೇರಿಸಿ.')],
        conclusion=W("Extension is proportional to load within the elastic limit (Hooke's law), and the slope gives the spring constant.", 'प्रत्यास्थता सीमा के भीतर विस्तार भार के अनुक्रमानुपाती है (हुक का नियम), और प्रवणता से स्प्रिंग नियतांक मिलता है।', 'ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ವಿಸ್ತರಣೆ ಭಾರಕ್ಕೆ ಅನುಪಾತೀಯ (ಹುಕ್ ನಿಯಮ); ಇಳಿಜಾರು ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What is the unit of the spring constant?', 'स्प्रिंग नियतांक की इकाई क्या है?', 'ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕದ ಏಕಮಾನ ಯಾವುದು?'), W('N/m.', 'N/m.', 'N/m.')),
              Q(W('What is the elastic limit?', 'प्रत्यास्थता सीमा क्या है?', 'ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿ ಎಂದರೇನು?'), W('The largest load after which the spring still returns to its original length.', 'वह अधिकतम भार जिसके बाद भी स्प्रिंग अपनी मूल लंबाई पर लौट आती है।', 'ಸ್ಪ್ರಿಂಗ್ ತನ್ನ ಮೂಲ ಉದ್ದಕ್ಕೆ ಮರಳುವ ಗರಿಷ್ಠ ಭಾರ.')),
              Q(W('Two equal springs in series: what is the spring constant?', 'दो समान स्प्रिंग श्रेणी में हों तो स्प्रिंग नियतांक क्या होगा?', 'ಎರಡು ಸಮಾನ ಸ್ಪ್ರಿಂಗ್‌ಗಳು ಸರಣಿಯಲ್ಲಿದ್ದರೆ ಸ್ಥಿರಾಂಕ ಎಷ್ಟು?'), W('k/2: the pair stretches twice as much.', 'k/2: युग्म दोगुना खिंचता है।', 'k/2: ಜೋಡಿ ಎರಡು ಪಟ್ಟು ಹಿಗ್ಗುತ್ತದೆ.'))])

    lab(id='spring-mass-oscillation', bench='spring-mass', levels=[11], **mech,
        keywords=['oscillations', 'spring', 'simple harmonic motion', 'time period', 'spring constant', 'shm'],
        title=W('Time period of a loaded spring', 'भारित स्प्रिंग का आवर्तकाल', 'ಭಾರಿತ ಸ್ಪ್ರಿಂಗ್‌ನ ಆವರ್ತಕಾಲ'),
        summary=W('Time 20 oscillations for different masses and find k from the graph of T² against m.', 'विभिन्न द्रव्यमानों के लिए 20 दोलनों का समय लें और T² तथा m के ग्राफ़ से k ज्ञात करें।', 'ಬೇರೆ ಬೇರೆ ದ್ರವ್ಯರಾಶಿಗಳಿಗೆ 20 ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆದು T² ಮತ್ತು m ನಕ್ಷೆಯಿಂದ k ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the force constant of a spring from the time period of a mass oscillating on it.', 'स्प्रिंग पर दोलन करते द्रव्यमान के आवर्तकाल से स्प्रिंग का बल नियतांक ज्ञात करना।', 'ಸ್ಪ್ರಿಂಗ್ ಮೇಲೆ ಆಂದೋಲಿಸುವ ದ್ರವ್ಯರಾಶಿಯ ಆವರ್ತಕಾಲದಿಂದ ಸ್ಪ್ರಿಂಗ್‌ನ ಬಲ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A mass on a spring performs simple harmonic motion with T = 2π√(m/k). So T² = (4π²/k) m: a straight line whose slope gives k. A part of the spring’s own mass also moves, so the line meets the m-axis slightly below zero.', 'स्प्रिंग पर द्रव्यमान सरल आवर्त गति करता है जिसका T = 2π√(m/k). अतः T² = (4π²/k) m: एक सीधी रेखा जिसकी प्रवणता से k मिलता है। स्प्रिंग के अपने द्रव्यमान का कुछ भाग भी चलता है, इसलिए रेखा m-अक्ष को शून्य से थोड़ा पीछे काटती है।', 'ಸ್ಪ್ರಿಂಗ್ ಮೇಲಿನ ದ್ರವ್ಯರಾಶಿ T = 2π√(m/k) ಇರುವ ಸರಳ ಆವರ್ತ ಚಲನೆ ಮಾಡುತ್ತದೆ. ಆದ್ದರಿಂದ T² = (4π²/k) m: ಇಳಿಜಾರು k ನೀಡುವ ಸರಳರೇಖೆ. ಸ್ಪ್ರಿಂಗ್‌ನ ಸ್ವಂತ ದ್ರವ್ಯರಾಶಿಯ ಭಾಗವೂ ಚಲಿಸುವುದರಿಂದ ರೇಖೆ m-ಅಕ್ಷವನ್ನು ಶೂನ್ಯಕ್ಕಿಂತ ಸ್ವಲ್ಪ ಹಿಂದೆ ಛೇದಿಸುತ್ತದೆ.'),
        apparatus=[W('Helical spring', 'कुंडलित स्प्रिंग', 'ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್'), STAND, WEIGHTS, STOPWATCH],
        steps=[W('Hang a 50 g load and pull it down a little; release it.', '50 g भार लटकाकर थोड़ा नीचे खींचें; छोड़ दें।', '50 g ಭಾರ ತೂಗುಹಾಕಿ ಸ್ವಲ್ಪ ಕೆಳಗೆ ಎಳೆದು ಬಿಡಿ.'),
               W('Time 20 complete oscillations, starting as the load passes the mean position.', 'भार के माध्य स्थिति से गुजरते ही शुरू करके 20 पूर्ण दोलनों का समय लें।', 'ಭಾರ ಮಧ್ಯಸ್ಥಾನ ದಾಟುವಾಗ ಆರಂಭಿಸಿ 20 ಪೂರ್ಣ ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ.'),
               W('Repeat for loads up to 400 g.', '400 g तक के भारों के लिए दोहराएँ।', '400 g ವರೆಗಿನ ಭಾರಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Plot T² against m and find k = 4π² ÷ slope.', 'T² और m का ग्राफ़ बनाएँ और k = 4π² ÷ प्रवणता ज्ञात करें।', 'T² ಮತ್ತು m ನಕ್ಷೆ ಎಳೆದು k = 4π² ÷ ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ.')],
        precautions=[W('Keep the amplitude small and the motion vertical.', 'आयाम छोटा और गति ऊर्ध्वाधर रखें।', 'ವಿಸ್ತಾರ ಸಣ್ಣದಾಗಿ, ಚಲನೆ ಲಂಬವಾಗಿರಲಿ.'), W('Time many oscillations, not one.', 'एक नहीं, कई दोलनों का समय लें।', 'ಒಂದಲ್ಲ, ಹಲವು ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ.'), P_REPEAT],
        conclusion=W('T² increases linearly with the mass, and the slope gives the same spring constant as the static method.', 'T² द्रव्यमान के साथ रैखिक रूप से बढ़ता है, और प्रवणता से वही स्प्रिंग नियतांक मिलता है जो स्थैतिक विधि से।', 'T² ದ್ರವ್ಯರಾಶಿಯೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಹೆಚ್ಚುತ್ತದೆ; ಇಳಿಜಾರು ಸ್ಥಿರ ವಿಧಾನದಷ್ಟೇ ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Does T depend on the amplitude?', 'क्या T आयाम पर निर्भर करता है?', 'T ವಿಸ್ತಾರವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?'), W('No, not for simple harmonic motion.', 'नहीं, सरल आवर्त गति में नहीं।', 'ಇಲ್ಲ, ಸರಳ ಆವರ್ತ ಚಲನೆಯಲ್ಲಿ ಇಲ್ಲ.')),
              Q(W('How would T change on the Moon?', 'चंद्रमा पर T कैसे बदलेगा?', 'ಚಂದ್ರನ ಮೇಲೆ T ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?'), W('Not at all: T = 2π√(m/k) has no g in it.', 'बिल्कुल नहीं: T = 2π√(m/k) में g नहीं है।', 'ಒಂದಿಷ್ಟೂ ಇಲ್ಲ: T = 2π√(m/k) ಯಲ್ಲಿ g ಇಲ್ಲ.')),
              Q(W('If the mass is made four times, what happens to T?', 'द्रव्यमान चार गुना करने पर T का क्या होगा?', 'ದ್ರವ್ಯರಾಶಿಯನ್ನು ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ T ಏನಾಗುತ್ತದೆ?'), W('It doubles.', 'यह दोगुना हो जाता है।', 'ಅದು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ.'))])

    lab(id='inclined-plane', bench='incline', levels=[11], **mech,
        keywords=['inclined plane', 'laws of motion', 'force', 'component of weight', 'gravity'],
        title=W('Force along an inclined plane', 'आनत तल के अनुदिश बल', 'ಓರೆ ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ'),
        summary=W('Hold a roller on a slope with a spring balance and see how the force changes with the angle.', 'ढलान पर एक रोलर को कमानीदार तुला से रोकें और देखें कि कोण के साथ बल कैसे बदलता है।', 'ಇಳಿಜಾರಿನ ಮೇಲೆ ರೋಲರನ್ನು ಸ್ಪ್ರಿಂಗ್ ತುಲಾ ಹಿಡಿದಿಡಿ, ಕೋನದೊಂದಿಗೆ ಬಲ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ.'),
        aim=W('To find the downward force along an inclined plane on a roller due to gravity and study its relation with the angle of inclination.', 'गुरुत्व के कारण आनत तल पर रोलर पर नीचे की ओर लगने वाला बल ज्ञात करना और झुकाव कोण से उसका संबंध देखना।', 'ಗುರುತ್ವದಿಂದ ಓರೆ ಸಮತಲದ ಮೇಲೆ ರೋಲರ್ ಮೇಲೆ ಇಳಿಜಾರಿನ ಉದ್ದಕ್ಕೂ ಕೆಳಮುಖ ಬಲ ಕಂಡುಹಿಡಿದು ಓರೆ ಕೋನದೊಂದಿಗೆ ಅದರ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('The weight W of the roller has a component W sin θ along the plane and W cos θ into it. On a smooth plane the spring balance must pull up the slope with F = W sin θ, so F against sin θ is a straight line through the origin of slope W.', 'रोलर के भार W का एक घटक तल के अनुदिश W sin θ और तल में W cos θ होता है। चिकने तल पर कमानीदार तुला को ढलान पर ऊपर F = W sin θ से खींचना पड़ता है, इसलिए F और sin θ का ग्राफ़ मूल बिंदु से जाने वाली W प्रवणता की सीधी रेखा है।', 'ರೋಲರ್‌ನ ತೂಕ W ಗೆ ಸಮತಲದ ಉದ್ದಕ್ಕೂ W sin θ ಮತ್ತು ಒಳಗೆ W cos θ ಘಟಕಗಳಿವೆ. ನಯ ಸಮತಲದಲ್ಲಿ ಸ್ಪ್ರಿಂಗ್ ತುಲಾ ಇಳಿಜಾರಿನ ಮೇಲೆ F = W sin θ ದಿಂದ ಎಳೆಯಬೇಕು; ಆದ್ದರಿಂದ F ಮತ್ತು sin θ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ W ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ.'),
        apparatus=[W('Inclined plane with a protractor', 'चाँदा सहित आनत तल', 'ಕೋನಮಾಪಕ ಸಹಿತ ಓರೆ ಸಮತಲ'), W('Roller (500 g)', 'रोलर (500 g)', 'ರೋಲರ್ (500 g)'), W('Spring balance', 'कमानीदार तुला', 'ಸ್ಪ್ರಿಂಗ್ ತುಲಾ'), W('Thread', 'धागा', 'ದಾರ')],
        steps=[W('Weigh the roller with the spring balance.', 'कमानीदार तुला से रोलर का भार लें।', 'ಸ್ಪ್ರಿಂಗ್ ತುಲಾದಿಂದ ರೋಲರ್ ತೂಕ ಮಾಡಿ.'),
               W('Set the plane at 10° and hold the roller still with the balance parallel to the plane. Read F.', 'तल को 10° पर रखें और तुला को तल के समांतर रखकर रोलर को स्थिर रोकें। F पढ़ें।', 'ಸಮತಲವನ್ನು 10° ನಲ್ಲಿಡಿ, ತುಲಾವನ್ನು ಸಮತಲಕ್ಕೆ ಸಮಾಂತರವಾಗಿ ಹಿಡಿದು ರೋಲರನ್ನು ನಿಲ್ಲಿಸಿ. F ಓದಿ.'),
               W('Repeat for 20°, 30°, 40° and 50°.', '20°, 30°, 40° और 50° के लिए दोहराएँ।', '20°, 30°, 40° ಮತ್ತು 50° ಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Plot F against sin θ and compare the slope with the weight.', 'F और sin θ का ग्राफ़ बनाएँ और प्रवणता की तुलना भार से करें।', 'F ಮತ್ತು sin θ ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರನ್ನು ತೂಕದೊಂದಿಗೆ ಹೋಲಿಸಿ.')],
        precautions=[W('Keep the thread and balance parallel to the plane.', 'धागा और तुला तल के समांतर रखें।', 'ದಾರ ಮತ್ತು ತುಲಾ ಸಮತಲಕ್ಕೆ ಸಮಾಂತರವಾಗಿರಲಿ.'), W('Use a roller with little friction.', 'कम घर्षण वाला रोलर लें।', 'ಕಡಿಮೆ ಘರ್ಷಣೆಯ ರೋಲರ್ ಬಳಸಿ.'), P_ZERO],
        conclusion=W('The force along the plane is W sin θ: it grows with the angle and the F–sin θ graph is a straight line through the origin.', 'तल के अनुदिश बल W sin θ है: यह कोण के साथ बढ़ता है और F–sin θ ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है।', 'ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ W sin θ: ಕೋನದೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ; F–sin θ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ.'),
        viva=[Q(W('What is the force along the plane at 90°?', '90° पर तल के अनुदिश बल कितना है?', '90° ನಲ್ಲಿ ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ ಎಷ್ಟು?'), W('The full weight W.', 'पूरा भार W.', 'ಪೂರ್ಣ ತೂಕ W.')),
              Q(W('Why are mountain roads made winding?', 'पहाड़ी सड़कें घुमावदार क्यों बनाई जाती हैं?', 'ಬೆಟ್ಟದ ರಸ್ತೆಗಳನ್ನು ಏಕೆ ಸುತ್ತುಬಳಸಿ ಮಾಡುತ್ತಾರೆ?'), W('A smaller slope means a smaller W sin θ to overcome.', 'कम ढलान का अर्थ है कम W sin θ पार करना।', 'ಕಡಿಮೆ ಇಳಿಜಾರು ಎಂದರೆ ಎದುರಿಸಬೇಕಾದ W sin θ ಕಡಿಮೆ.')),
              Q(W('What is the normal reaction on the plane?', 'तल पर अभिलंब प्रतिक्रिया कितनी है?', 'ಸಮತಲದ ಮೇಲಿನ ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆ ಎಷ್ಟು?'), W('W cos θ, where θ is the angle of the incline.', 'W cos θ, जहाँ θ आनत तल का कोण है।', 'W cos θ, ಇಲ್ಲಿ θ ಓರೆ ಸಮತಲದ ಕೋನ.'))])

    lab(id='limiting-friction', bench='friction', levels=[11], **mech,
        keywords=['friction', 'limiting friction', 'coefficient of friction', 'normal reaction', 'laws of motion'],
        title=W('Limiting friction and the coefficient of friction', 'सीमांत घर्षण और घर्षण गुणांक', 'ಮಿತಿ ಘರ್ಷಣೆ ಮತ್ತು ಘರ್ಷಣ ಗುಣಾಂಕ'),
        summary=W('Find the least pull that starts a block sliding for several normal forces; the slope is μ.', 'कई अभिलंब बलों के लिए वह न्यूनतम खिंचाव ज्ञात करें जिससे गुटका खिसकने लगे; प्रवणता μ है।', 'ಹಲವು ಲಂಬ ಬಲಗಳಿಗೆ ಬ್ಲಾಕ್ ಜಾರಲು ಆರಂಭಿಸುವ ಕನಿಷ್ಠ ಎಳೆತ ಕಂಡುಹಿಡಿಯಿರಿ; ಇಳಿಜಾರು μ.'),
        aim=W('To study the relationship between the force of limiting friction and the normal reaction and to find the coefficient of friction between a block and a horizontal surface.', 'सीमांत घर्षण बल और अभिलंब प्रतिक्रिया के संबंध का अध्ययन करना और गुटके तथा क्षैतिज सतह के बीच घर्षण गुणांक ज्ञात करना।', 'ಮಿತಿ ಘರ್ಷಣ ಬಲ ಮತ್ತು ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆಯ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡಿ, ಬ್ಲಾಕ್ ಮತ್ತು ಸಮತಲ ಮೇಲ್ಮೈ ನಡುವಿನ ಘರ್ಷಣ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Friction opposes the start of sliding up to a maximum, the limiting friction F, which is proportional to the normal reaction N: F = μN. The slope of F against N is the coefficient of static friction μ, which depends on the two surfaces.', 'घर्षण खिसकने की शुरुआत का एक अधिकतम मान तक विरोध करता है, यह सीमांत घर्षण F है, जो अभिलंब प्रतिक्रिया N के अनुक्रमानुपाती है: F = μN. F और N की प्रवणता स्थैतिक घर्षण गुणांक μ है, जो दोनों सतहों पर निर्भर करता है।', 'ಘರ್ಷಣೆ ಜಾರುವಿಕೆಯ ಆರಂಭವನ್ನು ಒಂದು ಗರಿಷ್ಠದವರೆಗೆ ವಿರೋಧಿಸುತ್ತದೆ; ಅದು ಮಿತಿ ಘರ್ಷಣೆ F, ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆ N ಗೆ ಅನುಪಾತೀಯ: F = μN. F ಮತ್ತು N ಇಳಿಜಾರು ಸ್ಥಿರ ಘರ್ಷಣ ಗುಣಾಂಕ μ; ಅದು ಎರಡು ಮೇಲ್ಮೈಗಳನ್ನು ಅವಲಂಬಿಸಿದೆ.'),
        apparatus=[W('Wooden block with a hook', 'हुक सहित लकड़ी का गुटका', 'ಕೊಕ್ಕೆ ಸಹಿತ ಮರದ ಬ್ಲಾಕ್'), W('Horizontal board with a pulley', 'घिरनी सहित क्षैतिज तख़्ता', 'ರಾಟೆ ಸಹಿತ ಸಮತಲ ಹಲಗೆ'), W('Scale pan and weights', 'पलड़ा और बाट', 'ತಟ್ಟೆ ಮತ್ತು ತೂಕಗಳು'), W('Spirit level and thread', 'स्पिरिट लेवल और धागा', 'ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಮತ್ತು ದಾರ')],
        steps=[W('Level the board. Tie the block to the pan over the pulley.', 'तख़्ते को समतल करें। गुटके को घिरनी के ऊपर से पलड़े से बाँधें।', 'ಹಲಗೆಯನ್ನು ಸಮತಲಗೊಳಿಸಿ. ಬ್ಲಾಕನ್ನು ರಾಟೆಯ ಮೇಲಿಂದ ತಟ್ಟೆಗೆ ಕಟ್ಟಿ.'),
               W('Add small weights to the pan until the block just starts to slide when tapped. Pan + weights gives F.', 'पलड़े में छोटे बाट तब तक डालें जब तक थपथपाने पर गुटका बस खिसकने न लगे। पलड़ा + बाट से F मिलता है।', 'ತಟ್ಟಿದಾಗ ಬ್ಲಾಕ್ ಕೇವಲ ಜಾರಲು ಆರಂಭಿಸುವವರೆಗೆ ತಟ್ಟೆಗೆ ಸಣ್ಣ ತೂಕ ಸೇರಿಸಿ. ತಟ್ಟೆ + ತೂಕ F ನೀಡುತ್ತದೆ.'),
               W('Put masses on the block to change N and repeat.', 'N बदलने के लिए गुटके पर द्रव्यमान रखें और दोहराएँ।', 'N ಬದಲಿಸಲು ಬ್ಲಾಕ್ ಮೇಲೆ ದ್ರವ್ಯರಾಶಿ ಇಟ್ಟು ಪುನರಾವರ್ತಿಸಿ.'),
               W('Plot F against N and find μ from the slope; compare different surfaces.', 'F और N का ग्राफ़ बनाकर प्रवणता से μ ज्ञात करें; विभिन्न सतहों की तुलना करें।', 'F ಮತ್ತು N ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರಿನಿಂದ μ ಕಂಡುಹಿಡಿಯಿರಿ; ಬೇರೆ ಮೇಲ್ಮೈಗಳನ್ನು ಹೋಲಿಸಿ.')],
        precautions=[W('Keep the thread horizontal and the pulley frictionless.', 'धागा क्षैतिज और घिरनी घर्षणरहित रखें।', 'ದಾರ ಸಮತಲ, ರಾಟೆ ಘರ್ಷಣೆರಹಿತವಾಗಿರಲಿ.'), W('Add weights in small steps near the point of sliding.', 'खिसकने के बिंदु के पास छोटे चरणों में बाट डालें।', 'ಜಾರುವ ಬಿಂದುವಿನ ಹತ್ತಿರ ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ತೂಕ ಸೇರಿಸಿ.'), W('Keep the surfaces clean and dry.', 'सतहें साफ़ और सूखी रखें।', 'ಮೇಲ್ಮೈಗಳು ಸ್ವಚ್ಛ ಮತ್ತು ಒಣಗಿರಲಿ.')],
        conclusion=W('Limiting friction is directly proportional to the normal reaction; the coefficient of friction is constant for a pair of surfaces and differs between surfaces.', 'सीमांत घर्षण अभिलंब प्रतिक्रिया के अनुक्रमानुपाती है; घर्षण गुणांक दो सतहों के युग्म के लिए नियत है और अलग सतहों के लिए भिन्न।', 'ಮಿತಿ ಘರ್ಷಣೆ ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆಗೆ ನೇರ ಅನುಪಾತೀಯ; ಘರ್ಷಣ ಗುಣಾಂಕ ಒಂದು ಮೇಲ್ಮೈ ಜೋಡಿಗೆ ಸ್ಥಿರ, ಬೇರೆ ಮೇಲ್ಮೈಗಳಿಗೆ ಭಿನ್ನ.'),
        viva=[Q(W('Does limiting friction depend on the area of contact?', 'क्या सीमांत घर्षण संपर्क क्षेत्रफल पर निर्भर करता है?', 'ಮಿತಿ ಘರ್ಷಣೆ ಸಂಪರ್ಕ ವಿಸ್ತೀರ್ಣವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?'), W('No (to a good approximation).', 'नहीं (अच्छे सन्निकटन तक)।', 'ಇಲ್ಲ (ಉತ್ತಮ ಅಂದಾಜಿಗೆ).')),
              Q(W('Which is larger, static or kinetic friction?', 'स्थैतिक या गतिज घर्षण, कौन बड़ा है?', 'ಸ್ಥಿರ ಅಥವಾ ಚಲನ ಘರ್ಷಣೆ, ಯಾವುದು ದೊಡ್ಡದು?'), W('Limiting static friction is slightly larger.', 'सीमांत स्थैतिक घर्षण थोड़ा बड़ा है।', 'ಮಿತಿ ಸ್ಥಿರ ಘರ್ಷಣೆ ಸ್ವಲ್ಪ ದೊಡ್ಡದು.')),
              Q(W('Why is the block tapped gently?', 'गुटके को हल्के से क्यों थपथपाते हैं?', 'ಬ್ಲಾಕನ್ನು ಏಕೆ ಮೃದುವಾಗಿ ತಟ್ಟುತ್ತಾರೆ?'), W('To start it when the pull just equals limiting friction, so the reading is not too high.', 'ताकि खिंचाव सीमांत घर्षण के बराबर होते ही वह चल पड़े, और पाठ्यांक अधिक न आए।', 'ಎಳೆತ ಮಿತಿ ಘರ್ಷಣೆಗೆ ಸಮವಾದಾಗಲೇ ಅದು ಚಲಿಸಲು, ಓದು ಹೆಚ್ಚು ಬರದಂತೆ.'))])

    lab(id='projectile-motion', bench='projectile', levels=[11], mode='explore', **mech,
        keywords=['projectile', 'projectile motion', 'motion in a plane', 'range', 'trajectory'],
        title=W('Projectile motion', 'प्रक्षेप्य गति', 'ಉತ್ಕ್ಷೇಪಕ ಚಲನೆ'),
        summary=W('Launch a ball at different speeds and angles and find which angle goes farthest.', 'गेंद को अलग-अलग चाल और कोणों पर फेंकें और पता लगाएँ कि कौन-सा कोण सबसे दूर जाता है।', 'ಚೆಂಡನ್ನು ಬೇರೆ ಬೇರೆ ವೇಗ ಮತ್ತು ಕೋನಗಳಲ್ಲಿ ಎಸೆದು ಯಾವ ಕೋನ ಅತಿ ದೂರ ಹೋಗುತ್ತದೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To study how the range, height and time of flight of a projectile depend on its speed and angle of launch.', 'यह अध्ययन करना कि प्रक्षेप्य की परास, ऊँचाई और उड़ान काल उसकी चाल और प्रक्षेपण कोण पर कैसे निर्भर करते हैं।', 'ಉತ್ಕ್ಷೇಪಕದ ವ್ಯಾಪ್ತಿ, ಎತ್ತರ ಮತ್ತು ಹಾರಾಟ ಸಮಯ ಅದರ ವೇಗ ಮತ್ತು ಉಡಾವಣಾ ಕೋನವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿವೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Without air resistance the horizontal velocity stays constant and the vertical motion has acceleration g. From the ground: time T = 2u sin θ / g, greatest height H = u² sin² θ / 2g, range R = u² sin 2θ / g, largest at 45°; complementary angles give the same range.', 'वायु प्रतिरोध के बिना क्षैतिज वेग नियत रहता है और ऊर्ध्वाधर गति में त्वरण g होता है। भूमि से: समय T = 2u sin θ / g, अधिकतम ऊँचाई H = u² sin² θ / 2g, परास R = u² sin 2θ / g, जो 45° पर सबसे अधिक है; पूरक कोण समान परास देते हैं।', 'ಗಾಳಿಯ ಪ್ರತಿರೋಧವಿಲ್ಲದಿದ್ದರೆ ಸಮತಲ ವೇಗ ಸ್ಥಿರ, ಲಂಬ ಚಲನೆಗೆ ವೇಗೋತ್ಕರ್ಷ g. ನೆಲದಿಂದ: ಸಮಯ T = 2u sin θ / g, ಗರಿಷ್ಠ ಎತ್ತರ H = u² sin² θ / 2g, ವ್ಯಾಪ್ತಿ R = u² sin 2θ / g, 45° ನಲ್ಲಿ ಗರಿಷ್ಠ; ಪೂರಕ ಕೋನಗಳು ಒಂದೇ ವ್ಯಾಪ್ತಿ ನೀಡುತ್ತವೆ.'),
        apparatus=[W('Projectile launcher with angle scale', 'कोण पैमाने सहित प्रक्षेप्य प्रक्षेपक', 'ಕೋನ ಅಳತೆ ಸಹಿತ ಉತ್ಕ್ಷೇಪಕ ಉಡಾವಕ'), W('Ball', 'गेंद', 'ಚೆಂಡು'), W('Measuring tape', 'मापक फ़ीता', 'ಅಳತೆ ಪಟ್ಟಿ'), STOPWATCH],
        steps=[W('Set a speed and launch at 30°; note the range, height and time.', 'एक चाल तय करके 30° पर प्रक्षेपित करें; परास, ऊँचाई और समय लिखें।', 'ಒಂದು ವೇಗ ಹೊಂದಿಸಿ 30° ಯಲ್ಲಿ ಉಡಾಯಿಸಿ; ವ್ಯಾಪ್ತಿ, ಎತ್ತರ ಮತ್ತು ಸಮಯ ಬರೆಯಿರಿ.'),
               W('Repeat at 45° and 60° with the same speed.', 'उसी चाल से 45° और 60° पर दोहराएँ।', 'ಅದೇ ವೇಗದಲ್ಲಿ 45° ಮತ್ತು 60° ಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Try other angles and find the one with the largest range.', 'दूसरे कोण आज़माएँ और सबसे अधिक परास वाला कोण ढूँढें।', 'ಬೇರೆ ಕೋನಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ ಗರಿಷ್ಠ ವ್ಯಾಪ್ತಿಯ ಕೋನ ಹುಡುಕಿ.'),
               W('Launch from a height and on the Moon, and explain the differences.', 'ऊँचाई से और चंद्रमा पर प्रक्षेपित करें, और अंतर समझाएँ।', 'ಎತ್ತರದಿಂದ ಮತ್ತು ಚಂದ್ರನ ಮೇಲೆ ಉಡಾಯಿಸಿ, ವ್ಯತ್ಯಾಸ ವಿವರಿಸಿ.')],
        precautions=[W('Change one thing at a time.', 'एक बार में एक ही चीज़ बदलें।', 'ಒಮ್ಮೆಗೆ ಒಂದೇ ಅಂಶ ಬದಲಿಸಿ.'), W('In a real launcher, never aim at people.', 'असली प्रक्षेपक में कभी लोगों की ओर निशाना न लगाएँ।', 'ನಿಜವಾದ ಉಡಾವಕದಲ್ಲಿ ಎಂದೂ ಜನರತ್ತ ಗುರಿ ಇಡಬೇಡಿ.')],
        conclusion=W('From level ground the range is largest at 45°, complementary angles give equal ranges, and the path is a parabola.', 'समतल भूमि से परास 45° पर सबसे अधिक होती है, पूरक कोण समान परास देते हैं, और पथ परवलय है।', 'ಸಮ ನೆಲದಿಂದ ವ್ಯಾಪ್ತಿ 45° ನಲ್ಲಿ ಗರಿಷ್ಠ; ಪೂರಕ ಕೋನಗಳು ಸಮ ವ್ಯಾಪ್ತಿ ನೀಡುತ್ತವೆ; ಪಥ ಪರವಲಯ.'),
        viva=[Q(W('What is the velocity at the top of the path?', 'पथ के शीर्ष पर वेग कितना होता है?', 'ಪಥದ ತುದಿಯಲ್ಲಿ ವೇಗ ಎಷ್ಟು?'), W('Only the horizontal part, u cos θ.', 'केवल क्षैतिज भाग, u cos θ.', 'ಸಮತಲ ಭಾಗ ಮಾತ್ರ, u cos θ.')),
              Q(W('How does air resistance change the best angle?', 'वायु प्रतिरोध सर्वोत्तम कोण को कैसे बदलता है?', 'ಗಾಳಿಯ ಪ್ರತಿರೋಧ ಉತ್ತಮ ಕೋನವನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತದೆ?'), W('It makes it a little less than 45°.', 'यह उसे 45° से थोड़ा कम कर देता है।', 'ಅದು 45° ಗಿಂತ ಸ್ವಲ್ಪ ಕಡಿಮೆಯಾಗುತ್ತದೆ.')),
              Q(W('Which two angles give the same range as 20°?', '20° जितनी परास और कौन-सा कोण देता है?', '20° ಯಷ್ಟೇ ವ್ಯಾಪ್ತಿಯನ್ನು ಇನ್ನಾವ ಕೋನ ನೀಡುತ್ತದೆ?'), W('70°.', '70°.', '70°.'))])

    lab(id='collisions-momentum', bench='collision', levels=[11, 'ug'], mode='explore', **mech,
        keywords=['collision', 'collisions', 'momentum', 'conservation of momentum', 'elastic collision', 'inelastic collision', 'work energy and power'],
        title=W('Collisions and conservation of momentum', 'संघट्ट और संवेग संरक्षण', 'ಘರ್ಷಣೆಗಳು ಮತ್ತು ಸಂವೇಗ ಸಂರಕ್ಷಣೆ'),
        summary=W('Crash two carts on an air track and compare momentum and kinetic energy before and after.', 'वायु पथ पर दो गाड़ियों को टकराएँ और पहले तथा बाद के संवेग और गतिज ऊर्जा की तुलना करें।', 'ಗಾಳಿ ಹಾದಿಯಲ್ಲಿ ಎರಡು ಗಾಡಿಗಳನ್ನು ಢಿಕ್ಕಿಪಡಿಸಿ, ಮೊದಲು ಮತ್ತು ನಂತರದ ಸಂವೇಗ ಮತ್ತು ಚಲನ ಶಕ್ತಿಯನ್ನು ಹೋಲಿಸಿ.'),
        aim=W('To verify the conservation of momentum in elastic and inelastic collisions and compare the kinetic energy before and after.', 'प्रत्यास्थ और अप्रत्यास्थ संघट्टों में संवेग संरक्षण का सत्यापन करना और पहले तथा बाद की गतिज ऊर्जा की तुलना करना।', 'ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮತ್ತು ಅಸ್ಥಿತಿಸ್ಥಾಪಕ ಘರ್ಷಣೆಗಳಲ್ಲಿ ಸಂವೇಗ ಸಂರಕ್ಷಣೆ ಪರಿಶೀಲಿಸಿ ಮೊದಲು ಮತ್ತು ನಂತರದ ಚಲನ ಶಕ್ತಿಯನ್ನು ಹೋಲಿಸುವುದು.'),
        principle=W('With no outside force, total momentum m₁u₁ + m₂u₂ stays the same in every collision. Kinetic energy is also conserved only in an elastic collision (e = 1); when the carts stick (e = 0) the most energy turns into heat and sound.', 'बाहरी बल न होने पर कुल संवेग m₁u₁ + m₂u₂ हर संघट्ट में वही रहता है। गतिज ऊर्जा केवल प्रत्यास्थ संघट्ट (e = 1) में संरक्षित रहती है; गाड़ियाँ चिपक जाएँ (e = 0) तो सबसे अधिक ऊर्जा ऊष्मा और ध्वनि बन जाती है।', 'ಹೊರಗಿನ ಬಲವಿಲ್ಲದಿದ್ದರೆ ಒಟ್ಟು ಸಂವೇಗ m₁u₁ + m₂u₂ ಪ್ರತಿ ಘರ್ಷಣೆಯಲ್ಲೂ ಒಂದೇ. ಚಲನ ಶಕ್ತಿ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಘರ್ಷಣೆಯಲ್ಲಿ (e = 1) ಮಾತ್ರ ಸಂರಕ್ಷಿತ; ಗಾಡಿಗಳು ಅಂಟಿಕೊಂಡರೆ (e = 0) ಅತಿ ಹೆಚ್ಚು ಶಕ್ತಿ ಉಷ್ಣ ಮತ್ತು ಧ್ವನಿಯಾಗುತ್ತದೆ.'),
        apparatus=[W('Air track with blower', 'ब्लोअर सहित वायु पथ', 'ಊದುಕ ಸಹಿತ ಗಾಳಿ ಹಾದಿ'), W('Two gliders with spring or putty bumpers', 'स्प्रिंग या पुट्टी बंपर वाली दो गाड़ियाँ', 'ಸ್ಪ್ರಿಂಗ್ ಅಥವಾ ಪುಟ್ಟಿ ಬಂಪರ್‌ಗಳ ಎರಡು ಗಾಡಿಗಳು'), W('Photogates and timer', 'फ़ोटोगेट और टाइमर', 'ಫೋಟೋಗೇಟ್ ಮತ್ತು ಟೈಮರ್'), W('Extra masses', 'अतिरिक्त द्रव्यमान', 'ಹೆಚ್ಚುವರಿ ದ್ರವ್ಯರಾಶಿಗಳು')],
        steps=[W('Choose the masses and set cart 2 at rest in the middle.', 'द्रव्यमान चुनें और गाड़ी 2 को बीच में स्थिर रखें।', 'ದ್ರವ್ಯರಾಶಿಗಳನ್ನು ಆರಿಸಿ ಗಾಡಿ 2 ಅನ್ನು ಮಧ್ಯದಲ್ಲಿ ನಿಶ್ಚಲವಾಗಿಡಿ.'),
               W('Push cart 1 into it with spring bumpers (elastic); record the velocities before and after.', 'स्प्रिंग बंपर (प्रत्यास्थ) के साथ गाड़ी 1 को उससे टकराएँ; पहले और बाद के वेग लिखें।', 'ಸ್ಪ್ರಿಂಗ್ ಬಂಪರ್‌ಗಳೊಂದಿಗೆ (ಸ್ಥಿತಿಸ್ಥಾಪಕ) ಗಾಡಿ 1 ಅನ್ನು ಅದಕ್ಕೆ ಢಿಕ್ಕಿಹೊಡೆಸಿ; ಮೊದಲು ಮತ್ತು ನಂತರದ ವೇಗಗಳನ್ನು ದಾಖಲಿಸಿ.'),
               W('Repeat with putty (the carts stick) and with partly elastic bumpers.', 'पुट्टी (गाड़ियाँ चिपकती हैं) और आंशिक प्रत्यास्थ बंपरों के साथ दोहराएँ।', 'ಪುಟ್ಟಿ (ಗಾಡಿಗಳು ಅಂಟುತ್ತವೆ) ಮತ್ತು ಭಾಗಶಃ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಬಂಪರ್‌ಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Compare total momentum and kinetic energy before and after each collision.', 'हर संघट्ट से पहले और बाद के कुल संवेग तथा गतिज ऊर्जा की तुलना करें।', 'ಪ್ರತಿ ಘರ್ಷಣೆಯ ಮೊದಲು ಮತ್ತು ನಂತರದ ಒಟ್ಟು ಸಂವೇಗ ಮತ್ತು ಚಲನ ಶಕ್ತಿ ಹೋಲಿಸಿ.')],
        precautions=[W('Level the air track so the carts move at steady speed.', 'वायु पथ समतल करें ताकि गाड़ियाँ स्थिर चाल से चलें।', 'ಗಾಡಿಗಳು ಸ್ಥಿರ ವೇಗದಲ್ಲಿ ಚಲಿಸುವಂತೆ ಗಾಳಿ ಹಾದಿ ಸಮತಲಗೊಳಿಸಿ.'), W('Take velocities just before and just after the collision.', 'वेग संघट्ट से ठीक पहले और ठीक बाद लें।', 'ವೇಗಗಳನ್ನು ಘರ್ಷಣೆಯ ಸ್ವಲ್ಪ ಮೊದಲು ಮತ್ತು ಸ್ವಲ್ಪ ನಂತರ ತೆಗೆದುಕೊಳ್ಳಿ.')],
        conclusion=W('Momentum is conserved in every collision; kinetic energy is conserved only in the elastic one and the most is lost when the carts stick together.', 'संवेग हर संघट्ट में संरक्षित है; गतिज ऊर्जा केवल प्रत्यास्थ में संरक्षित है और गाड़ियाँ चिपकने पर सबसे अधिक नष्ट होती है।', 'ಸಂವೇಗ ಪ್ರತಿ ಘರ್ಷಣೆಯಲ್ಲೂ ಸಂರಕ್ಷಿತ; ಚಲನ ಶಕ್ತಿ ಸ್ಥಿತಿಸ್ಥಾಪಕದಲ್ಲಿ ಮಾತ್ರ; ಗಾಡಿಗಳು ಅಂಟಿದಾಗ ಅತಿ ಹೆಚ್ಚು ನಷ್ಟ.'),
        viva=[Q(W('What happens when equal masses collide elastically and one is at rest?', 'समान द्रव्यमान प्रत्यास्थ रूप से टकराएँ और एक स्थिर हो तो क्या होता है?', 'ಸಮ ದ್ರವ್ಯರಾಶಿಗಳು ಸ್ಥಿತಿಸ್ಥಾಪಕವಾಗಿ ಢಿಕ್ಕಿಯಾಗಿ ಒಂದು ನಿಶ್ಚಲವಾಗಿದ್ದರೆ ಏನಾಗುತ್ತದೆ?'), W('They exchange velocities: the first stops, the second moves off.', 'वे वेग बदल लेते हैं: पहली रुक जाती है, दूसरी चल पड़ती है।', 'ಅವು ವೇಗ ವಿನಿಮಯ ಮಾಡಿಕೊಳ್ಳುತ್ತವೆ: ಮೊದಲನೆಯದು ನಿಲ್ಲುತ್ತದೆ, ಎರಡನೆಯದು ಚಲಿಸುತ್ತದೆ.')),
              Q(W('What is the coefficient of restitution?', 'प्रत्यावस्थान गुणांक क्या है?', 'ಪುನಃಸ್ಥಾಪನ ಗುಣಾಂಕ ಎಂದರೇನು?'), W('Speed of separation ÷ speed of approach.', 'पृथक्करण चाल ÷ उपगमन चाल।', 'ಬೇರ್ಪಡುವ ವೇಗ ÷ ಸಮೀಪಿಸುವ ವೇಗ.')),
              Q(W('Where does the lost kinetic energy go?', 'नष्ट गतिज ऊर्जा कहाँ जाती है?', 'ನಷ್ಟವಾದ ಚಲನ ಶಕ್ತಿ ಎಲ್ಲಿಗೆ ಹೋಗುತ್ತದೆ?'), W('Into heat, sound and deformation.', 'ऊष्मा, ध्वनि और विरूपण में।', 'ಉಷ್ಣ, ಧ್ವನಿ ಮತ್ತು ವಿರೂಪಣೆಗೆ.'))])

    lab(id='youngs-modulus', bench='searle', levels=[11, 'ug'], **mech,
        keywords=["young's modulus", 'elasticity', 'searle', 'stress', 'strain', 'mechanical properties of solids'],
        title=W("Young's modulus of a wire (Searle's method)", 'तार का यंग प्रत्यास्थता गुणांक (सर्ल विधि)', 'ತಂತಿಯ ಯಂಗ್ ಗುಣಾಂಕ (ಸರ್ಲ್ ವಿಧಾನ)'),
        summary=W('Load a long wire, read the extension with a micrometer, and get Y from the load–extension slope.', 'लंबे तार पर भार डालें, माइक्रोमीटर से विस्तार पढ़ें, और भार–विस्तार प्रवणता से Y निकालें।', 'ಉದ್ದ ತಂತಿಗೆ ಭಾರ ಹಾಕಿ, ಮೈಕ್ರೋಮೀಟರ್‌ನಿಂದ ವಿಸ್ತರಣೆ ಓದಿ, ಭಾರ–ವಿಸ್ತರಣೆ ಇಳಿಜಾರಿನಿಂದ Y ಪಡೆಯಿರಿ.'),
        aim=W("To find Young's modulus of the material of a wire by Searle's method.", 'सर्ल विधि से तार के पदार्थ का यंग प्रत्यास्थता गुणांक ज्ञात करना।', 'ಸರ್ಲ್ ವಿಧಾನದಿಂದ ತಂತಿಯ ವಸ್ತುವಿನ ಯಂಗ್ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Young’s modulus Y = stress ÷ strain = (F/A) ÷ (ΔL/L), so ΔL = FL/(AY). A reference wire beside the test wire cancels sagging of the support and changes of temperature. The slope of ΔL against the load m gives Y = gL ÷ (πr² × slope).', 'यंग गुणांक Y = प्रतिबल ÷ विकृति = (F/A) ÷ (ΔL/L), अतः ΔL = FL/(AY). परीक्षण तार के पास का संदर्भ तार आधार के झुकने और ताप के बदलाव का प्रभाव मिटा देता है। ΔL और भार m की प्रवणता से Y = gL ÷ (πr² × प्रवणता) मिलता है।', 'ಯಂಗ್ ಗುಣಾಂಕ Y = ಒತ್ತಡ ÷ ವಿಕಾರ = (F/A) ÷ (ΔL/L), ಆದ್ದರಿಂದ ΔL = FL/(AY). ಪರೀಕ್ಷಾ ತಂತಿಯ ಪಕ್ಕದ ಉಲ್ಲೇಖ ತಂತಿ ಆಧಾರದ ಬಾಗುವಿಕೆ ಮತ್ತು ತಾಪ ಬದಲಾವಣೆಯ ಪರಿಣಾಮ ರದ್ದುಗೊಳಿಸುತ್ತದೆ. ΔL ಮತ್ತು ಭಾರ m ಇಳಿಜಾರಿನಿಂದ Y = gL ÷ (πr² × ಇಳಿಜಾರು).'),
        apparatus=[W("Searle's apparatus with two identical wires", 'दो समान तारों सहित सर्ल उपकरण', 'ಎರಡು ಸಮಾನ ತಂತಿಗಳ ಸರ್ಲ್ ಉಪಕರಣ'), W('Micrometer screw and spirit level', 'माइक्रोमीटर पेंच और स्पिरिट लेवल', 'ಮೈಕ್ರೋಮೀಟರ್ ತಿರುಪು ಮತ್ತು ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್'), W('Slotted 0.5 kg weights', 'खाँचेदार 0.5 kg बाट', 'ಸೀಳು 0.5 kg ತೂಕಗಳು'), W('Screw gauge and metre scale', 'पेंच गेज और मीटर पैमाना', 'ಸ್ಕ್ರೂ ಗೇಜ್ ಮತ್ತು ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ')],
        steps=[W('Measure the length L and the diameter of the wire (in several places with the screw gauge).', 'तार की लंबाई L और व्यास मापें (पेंच गेज से कई स्थानों पर)।', 'ತಂತಿಯ ಉದ್ದ L ಮತ್ತು ವ್ಯಾಸ ಅಳೆಯಿರಿ (ಸ್ಕ್ರೂ ಗೇಜ್‌ನಿಂದ ಹಲವು ಸ್ಥಳಗಳಲ್ಲಿ).'),
               W('With a dead load on both wires, level the spirit level with the micrometer and read it.', 'दोनों तारों पर आरंभिक भार रखकर माइक्रोमीटर से स्पिरिट लेवल समतल करें और पढ़ें।', 'ಎರಡೂ ತಂತಿಗಳ ಮೇಲೆ ಆರಂಭಿಕ ಭಾರವಿಟ್ಟು ಮೈಕ್ರೋಮೀಟರ್‌ನಿಂದ ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಸಮತಲಗೊಳಿಸಿ ಓದಿ.'),
               W('Add 0.5 kg to the test wire, wait a minute, relevel and read. Continue up to 5 kg, then unload in steps.', 'परीक्षण तार पर 0.5 kg जोड़ें, एक मिनट रुकें, फिर समतल करके पढ़ें। 5 kg तक जारी रखें, फिर चरणों में भार हटाएँ।', 'ಪರೀಕ್ಷಾ ತಂತಿಗೆ 0.5 kg ಸೇರಿಸಿ, ಒಂದು ನಿಮಿಷ ಕಾದು, ಮತ್ತೆ ಸಮತಲಗೊಳಿಸಿ ಓದಿ. 5 kg ವರೆಗೆ ಮುಂದುವರಿಸಿ, ನಂತರ ಹಂತಗಳಲ್ಲಿ ಭಾರ ಇಳಿಸಿ.'),
               W('Plot extension against load and find the slope.', 'विस्तार और भार का ग्राफ़ बनाकर प्रवणता ज्ञात करें।', 'ವಿಸ್ತರಣೆ ಮತ್ತು ಭಾರ ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ.'),
               W('Work out Y = gL ÷ (πr² × slope) with its uncertainty.', 'Y = gL ÷ (πr² × प्रवणता) उसकी अनिश्चितता सहित निकालें।', 'Y = gL ÷ (πr² × ಇಳಿಜಾರು) ಅನಿಶ್ಚಿತತೆ ಸಹಿತ ಲೆಕ್ಕಿಸಿ.'), CSV],
        precautions=[W('Keep the load well within the elastic limit.', 'भार प्रत्यास्थता सीमा के काफ़ी भीतर रखें।', 'ಭಾರ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ಚೆನ್ನಾಗಿ ಇರಲಿ.'), W('Wait after each load change so the wire settles.', 'हर भार परिवर्तन के बाद प्रतीक्षा करें ताकि तार स्थिर हो जाए।', 'ಪ್ರತಿ ಭಾರ ಬದಲಾವಣೆಯ ನಂತರ ತಂತಿ ಸ್ಥಿರವಾಗುವವರೆಗೆ ಕಾಯಿರಿ.'),
                     W('Measure the diameter carefully: it enters squared.', 'व्यास ध्यान से मापें: यह वर्ग के रूप में आता है।', 'ವ್ಯಾಸವನ್ನು ಎಚ್ಚರದಿಂದ ಅಳೆಯಿರಿ: ಅದು ವರ್ಗವಾಗಿ ಬರುತ್ತದೆ.')],
        conclusion=W("Extension is proportional to load, and the slope gives Young's modulus of the wire close to the table value (about 2 × 10¹¹ Pa for steel).", 'विस्तार भार के अनुक्रमानुपाती है, और प्रवणता से तार का यंग गुणांक सारणी मान (स्टील के लिए लगभग 2 × 10¹¹ Pa) के निकट मिलता है।', 'ವಿಸ್ತರಣೆ ಭಾರಕ್ಕೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ತಂತಿಯ ಯಂಗ್ ಗುಣಾಂಕವನ್ನು ಕೋಷ್ಟಕ ಮೌಲ್ಯದ ಹತ್ತಿರ (ಉಕ್ಕಿಗೆ ಸುಮಾರು 2 × 10¹¹ Pa) ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why is a reference wire used?', 'संदर्भ तार क्यों प्रयोग होता है?', 'ಉಲ್ಲೇಖ ತಂತಿಯನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?'), W('It cancels the yielding of the support and expansion with temperature.', 'यह आधार के झुकने और ताप से प्रसार के प्रभाव को निरस्त करता है।', 'ಅದು ಆಧಾರದ ಬಾಗುವಿಕೆ ಮತ್ತು ತಾಪದಿಂದ ವಿಸ್ತರಣೆಯ ಪರಿಣಾಮವನ್ನು ರದ್ದುಗೊಳಿಸುತ್ತದೆ.')),
              Q(W('Does Y depend on the length of the wire?', 'क्या Y तार की लंबाई पर निर्भर करता है?', 'Y ತಂತಿಯ ಉದ್ದವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?'), W('No; it is a property of the material.', 'नहीं; यह पदार्थ का गुण है।', 'ಇಲ್ಲ; ಅದು ವಸ್ತುವಿನ ಗುಣ.')),
              Q(W('Which is more elastic, rubber or steel?', 'रबर और स्टील में कौन अधिक प्रत्यास्थ है?', 'ರಬ್ಬರ್ ಮತ್ತು ಉಕ್ಕಿನಲ್ಲಿ ಯಾವುದು ಹೆಚ್ಚು ಸ್ಥಿತಿಸ್ಥಾಪಕ?'), W('Steel: it has the larger Young’s modulus.', 'स्टील: इसका यंग गुणांक अधिक है।', 'ಉಕ್ಕು: ಅದರ ಯಂಗ್ ಗುಣಾಂಕ ಹೆಚ್ಚು.'))])

    lab(id='stokes-viscosity', bench='stokes', levels=[11], **mech,
        keywords=['viscosity', "stokes' law", 'terminal velocity', 'mechanical properties of fluids', 'glycerine'],
        title=W("Viscosity of glycerine by Stokes' law", 'स्टोक्स नियम से ग्लिसरीन की श्यानता', 'ಸ್ಟೋಕ್ಸ್ ನಿಯಮದಿಂದ ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತೆ'),
        summary=W('Time steel balls of different sizes falling through glycerine; terminal velocity grows as r².', 'विभिन्न आकार की स्टील की गोलियों का ग्लिसरीन में गिरने का समय लें; सीमांत वेग r² के अनुसार बढ़ता है।', 'ಬೇರೆ ಗಾತ್ರದ ಉಕ್ಕಿನ ಗುಂಡುಗಳು ಗ್ಲಿಸರಿನ್‌ನಲ್ಲಿ ಬೀಳುವ ಸಮಯ ಅಳೆಯಿರಿ; ಅಂತಿಮ ವೇಗ r² ನಂತೆ ಹೆಚ್ಚುತ್ತದೆ.'),
        aim=W('To find the coefficient of viscosity of glycerine by measuring the terminal velocity of small spheres.', 'छोटे गोलों का सीमांत वेग मापकर ग्लिसरीन का श्यानता गुणांक ज्ञात करना।', 'ಸಣ್ಣ ಗೋಳಗಳ ಅಂತಿಮ ವೇಗ ಅಳೆದು ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತಾ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('A small sphere falling through a viscous liquid soon moves at a steady terminal velocity, when its weight equals buoyancy plus viscous drag 6πηrv. Then v = 2r²(ρ − σ)g ÷ 9η: v against r² is a straight line through the origin, and η = 2(ρ − σ)g ÷ (9 × slope).', 'श्यान द्रव में गिरता छोटा गोला जल्दी ही स्थिर सीमांत वेग से चलने लगता है, जब उसका भार उत्प्लावन और श्यान कर्षण 6πηrv के योग के बराबर हो जाता है। तब v = 2r²(ρ − σ)g ÷ 9η: v और r² का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है, और η = 2(ρ − σ)g ÷ (9 × प्रवणता).', 'ಸ್ನಿಗ್ಧ ದ್ರವದಲ್ಲಿ ಬೀಳುವ ಸಣ್ಣ ಗೋಳ ಬೇಗ ಸ್ಥಿರ ಅಂತಿಮ ವೇಗ ಪಡೆಯುತ್ತದೆ; ಆಗ ಅದರ ತೂಕ ಪ್ಲವನ ಮತ್ತು ಸ್ನಿಗ್ಧ ಎಳೆತ 6πηrv ಮೊತ್ತಕ್ಕೆ ಸಮ. ಆಗ v = 2r²(ρ − σ)g ÷ 9η: v ಮತ್ತು r² ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ; η = 2(ρ − σ)g ÷ (9 × ಇಳಿಜಾರು).'),
        apparatus=[W('Tall glass jar of glycerine with two marks 20 cm apart', '20 cm दूरी पर दो निशानों वाला ग्लिसरीन का लंबा जार', '20 cm ಅಂತರದ ಎರಡು ಗುರುತುಗಳಿರುವ ಗ್ಲಿಸರಿನ್ ತುಂಬಿದ ಎತ್ತರದ ಜಾಡಿ'), W('Steel balls of different radii', 'विभिन्न त्रिज्याओं की स्टील गोलियाँ', 'ಬೇರೆ ತ್ರಿಜ್ಯಗಳ ಉಕ್ಕಿನ ಗುಂಡುಗಳು'), W('Screw gauge', 'पेंच गेज', 'ಸ್ಕ್ರೂ ಗೇಜ್'), STOPWATCH],
        steps=[W('Measure the radius of each ball with the screw gauge.', 'हर गोली की त्रिज्या पेंच गेज से मापें।', 'ಪ್ರತಿ ಗುಂಡಿನ ತ್ರಿಜ್ಯವನ್ನು ಸ್ಕ್ರೂ ಗೇಜ್‌ನಿಂದ ಅಳೆಯಿರಿ.'),
               W('Wet a ball with glycerine and drop it gently at the centre of the jar.', 'गोली को ग्लिसरीन से गीला करके जार के बीच में धीरे से गिराएँ।', 'ಗುಂಡನ್ನು ಗ್ಲಿಸರಿನ್‌ನಿಂದ ಒದ್ದೆ ಮಾಡಿ ಜಾಡಿಯ ಮಧ್ಯದಲ್ಲಿ ನಿಧಾನವಾಗಿ ಬೀಳಿಸಿ.'),
               W('Time its fall between the two marks (it has reached terminal velocity by the first mark).', 'दोनों निशानों के बीच गिरने का समय लें (पहले निशान तक यह सीमांत वेग पा चुकी होती है)।', 'ಎರಡು ಗುರುತುಗಳ ನಡುವೆ ಬೀಳುವ ಸಮಯ ಅಳೆಯಿರಿ (ಮೊದಲ ಗುರುತಿನ ಹೊತ್ತಿಗೆ ಅದು ಅಂತಿಮ ವೇಗ ಪಡೆದಿರುತ್ತದೆ).'),
               W('Repeat for each size; plot v against r² and work out η.', 'हर आकार के लिए दोहराएँ; v और r² का ग्राफ़ बनाकर η निकालें।', 'ಪ್ರತಿ ಗಾತ್ರಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; v ಮತ್ತು r² ನಕ್ಷೆ ಎಳೆದು η ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Drop the balls along the axis, away from the walls.', 'गोलियाँ अक्ष के अनुदिश, दीवारों से दूर गिराएँ।', 'ಗುಂಡುಗಳನ್ನು ಅಕ್ಷದ ಉದ್ದಕ್ಕೂ, ಗೋಡೆಗಳಿಂದ ದೂರ ಬೀಳಿಸಿ.'), W('Look at the marks at eye level to avoid parallax.', 'लंबन से बचने के लिए निशानों को आँख के स्तर पर देखें।', 'ಭ್ರಂಶ ತಪ್ಪಿಸಲು ಗುರುತುಗಳನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ನೋಡಿ.'), W('Note the temperature: viscosity falls quickly as it rises.', 'ताप लिखें: ताप बढ़ने पर श्यानता तेज़ी से घटती है।', 'ತಾಪ ಬರೆಯಿರಿ: ತಾಪ ಏರಿದಂತೆ ಸ್ನಿಗ್ಧತೆ ವೇಗವಾಗಿ ಇಳಿಯುತ್ತದೆ.')],
        conclusion=W('Terminal velocity is proportional to r², as Stokes’ law predicts, and the slope gives the viscosity of glycerine (about 1.4 Pa s at room temperature).', 'सीमांत वेग r² के अनुक्रमानुपाती है, जैसा स्टोक्स नियम बताता है, और प्रवणता से ग्लिसरीन की श्यानता (कमरे के ताप पर लगभग 1.4 Pa s) मिलती है।', 'ಸ್ಟೋಕ್ಸ್ ನಿಯಮ ಹೇಳುವಂತೆ ಅಂತಿಮ ವೇಗ r² ಗೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತೆ (ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಸುಮಾರು 1.4 Pa s) ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What is terminal velocity?', 'सीमांत वेग क्या है?', 'ಅಂತಿಮ ವೇಗ ಎಂದರೇನು?'), W('The steady velocity reached when the net force on the falling body is zero.', 'गिरती वस्तु पर कुल बल शून्य होने पर प्राप्त स्थिर वेग।', 'ಬೀಳುವ ವಸ್ತುವಿನ ಮೇಲಿನ ನಿವ್ವಳ ಬಲ ಶೂನ್ಯವಾದಾಗ ಸಿಗುವ ಸ್ಥಿರ ವೇಗ.')),
              Q(W('Why do raindrops not hurt us?', 'बारिश की बूँदें हमें चोट क्यों नहीं पहुँचातीं?', 'ಮಳೆಹನಿಗಳು ನಮಗೆ ಏಕೆ ನೋವು ಮಾಡುವುದಿಲ್ಲ?'), W('Air resistance limits them to a small terminal velocity.', 'वायु प्रतिरोध उन्हें छोटे सीमांत वेग तक सीमित रखता है।', 'ಗಾಳಿಯ ಪ್ರತಿರೋಧ ಅವುಗಳನ್ನು ಸಣ್ಣ ಅಂತಿಮ ವೇಗಕ್ಕೆ ಮಿತಿಗೊಳಿಸುತ್ತದೆ.')),
              Q(W('What is the SI unit of viscosity?', 'श्यानता का SI मात्रक क्या है?', 'ಸ್ನಿಗ್ಧತೆಯ SI ಏಕಮಾನ ಯಾವುದು?'), W('Pascal second (Pa s).', 'पास्कल सेकंड (Pa s).', 'ಪ್ಯಾಸ್ಕಲ್ ಸೆಕೆಂಡ್ (Pa s).'))])

    lab(id='surface-tension-capillary', bench='capillary', levels=[11], **mech,
        keywords=['surface tension', 'capillary rise', 'capillarity', 'mechanical properties of fluids'],
        title=W('Surface tension of water by capillary rise', 'केशिका उन्नयन से पानी का पृष्ठ तनाव', 'ಲೋಮನಾಳ ಏರಿಕೆಯಿಂದ ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ'),
        summary=W('Measure how high water climbs in tubes of different bore; h × r is constant and gives the surface tension.', 'विभिन्न छिद्र वाली नलियों में पानी कितना ऊपर चढ़ता है मापें; h × r नियत है और पृष्ठ तनाव देता है।', 'ಬೇರೆ ಬೇರೆ ರಂಧ್ರದ ನಳಿಕೆಗಳಲ್ಲಿ ನೀರು ಎಷ್ಟು ಏರುತ್ತದೆ ಅಳೆಯಿರಿ; h × r ಸ್ಥಿರ, ಅದು ಮೇಲ್ಮೈ ಒತ್ತಡ ನೀಡುತ್ತದೆ.'),
        aim=W('To find the surface tension of water by the capillary rise method.', 'केशिका उन्नयन विधि से पानी का पृष्ठ तनाव ज्ञात करना।', 'ಲೋಮನಾಳ ಏರಿಕೆ ವಿಧಾನದಿಂದ ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Water wets glass, and surface tension pulls a column up a narrow tube until its weight balances the upward pull: h = 2T cos θ ÷ (rρg). For clean glass θ ≈ 0, so T = hrρg ÷ 2 and h × r is the same for every tube.', 'पानी काँच को भिगोता है, और पृष्ठ तनाव संकरी नली में स्तंभ को तब तक ऊपर खींचता है जब तक उसका भार ऊपर के खिंचाव को संतुलित न कर दे: h = 2T cos θ ÷ (rρg). साफ़ काँच के लिए θ ≈ 0, अतः T = hrρg ÷ 2 और h × r हर नली के लिए समान है।', 'ನೀರು ಗಾಜನ್ನು ತೇವಗೊಳಿಸುತ್ತದೆ; ಮೇಲ್ಮೈ ಒತ್ತಡ ಕಿರಿದಾದ ನಳಿಕೆಯಲ್ಲಿ ಸ್ತಂಭವನ್ನು ಅದರ ತೂಕ ಮೇಲ್ಮುಖ ಎಳೆತವನ್ನು ಸಮತೋಲಿಸುವವರೆಗೆ ಏರಿಸುತ್ತದೆ: h = 2T cos θ ÷ (rρg). ಸ್ವಚ್ಛ ಗಾಜಿಗೆ θ ≈ 0; ಆದ್ದರಿಂದ T = hrρg ÷ 2, h × r ಪ್ರತಿ ನಳಿಕೆಗೂ ಒಂದೇ.'),
        apparatus=[W('Capillary tubes of different bores', 'विभिन्न छिद्रों की केशिका नलियाँ', 'ಬೇರೆ ರಂಧ್ರಗಳ ಲೋಮನಾಳಗಳು'), W('Beaker of clean water', 'साफ़ पानी का बीकर', 'ಸ್ವಚ್ಛ ನೀರಿನ ಬೀಕರ್'), W('Travelling microscope', 'चल सूक्ष्मदर्शी', 'ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ'), W('Clamp stand and pointer', 'क्लैंप स्टैंड और सूचक', 'ಕ್ಲ್ಯಾಂಪ್ ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಸೂಚಕ')],
        steps=[W('Clean the tube and clamp it vertically with its end in the water.', 'नली साफ़ करें और उसका सिरा पानी में रखकर उसे ऊर्ध्वाधर क्लैंप करें।', 'ನಳಿಕೆ ಸ್ವಚ್ಛಗೊಳಿಸಿ, ಅದರ ತುದಿ ನೀರಿನಲ್ಲಿರುವಂತೆ ಲಂಬವಾಗಿ ಕ್ಲ್ಯಾಂಪ್ ಮಾಡಿ.'),
               W('Focus the microscope on the bottom of the meniscus in the tube; then on the tip of a pointer just touching the water surface.', 'सूक्ष्मदर्शी को नली में मेनिस्कस के तल पर; फिर पानी की सतह को छूते सूचक की नोक पर फ़ोकस करें।', 'ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ನಳಿಕೆಯ ಮೆನಿಸ್ಕಸ್‌ನ ತಳದ ಮೇಲೆ; ನಂತರ ನೀರಿನ ಮೇಲ್ಮೈ ಮುಟ್ಟುವ ಸೂಚಕದ ತುದಿಯ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ.'),
               W('The difference of the readings is h. Measure the inner radius r of the tube.', 'पाठ्यांकों का अंतर h है। नली की भीतरी त्रिज्या r मापें।', 'ಓದುಗಳ ವ್ಯತ್ಯಾಸ h. ನಳಿಕೆಯ ಒಳ ತ್ರಿಜ್ಯ r ಅಳೆಯಿರಿ.'),
               W('Repeat with other tubes and work out T = hrρg ÷ 2.', 'दूसरी नलियों के साथ दोहराएँ और T = hrρg ÷ 2 निकालें।', 'ಬೇರೆ ನಳಿಕೆಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ T = hrρg ÷ 2 ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('The tube and water must be perfectly clean (grease lowers T).', 'नली और पानी पूरी तरह साफ़ हों (चिकनाई T को घटाती है)।', 'ನಳಿಕೆ ಮತ್ತು ನೀರು ಸಂಪೂರ್ಣ ಸ್ವಚ್ಛವಾಗಿರಲಿ (ಜಿಡ್ಡು T ಕಡಿಮೆ ಮಾಡುತ್ತದೆ).'), W('Keep the tube vertical.', 'नली ऊर्ध्वाधर रखें।', 'ನಳಿಕೆ ಲಂಬವಾಗಿರಲಿ.'), W('Note the temperature: T falls as it rises.', 'ताप लिखें: ताप बढ़ने पर T घटता है।', 'ತಾಪ ಬರೆಯಿರಿ: ತಾಪ ಏರಿದಂತೆ T ಇಳಿಯುತ್ತದೆ.')],
        conclusion=W('The narrower the tube the higher the water rises, with h × r constant; the surface tension of water is about 0.072 N/m.', 'नली जितनी संकरी उतना अधिक पानी चढ़ता है, h × r नियत रहता है; पानी का पृष्ठ तनाव लगभग 0.072 N/m है।', 'ನಳಿಕೆ ಎಷ್ಟು ಕಿರಿದೋ ನೀರು ಅಷ್ಟು ಹೆಚ್ಚು ಏರುತ್ತದೆ, h × r ಸ್ಥಿರ; ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ ಸುಮಾರು 0.072 N/m.'),
        viva=[Q(W('Why does mercury fall in a glass capillary?', 'काँच की केशिका में पारा नीचे क्यों जाता है?', 'ಗಾಜಿನ ಲೋಮನಾಳದಲ್ಲಿ ಪಾದರಸ ಏಕೆ ಇಳಿಯುತ್ತದೆ?'), W('It does not wet glass: its angle of contact is more than 90°.', 'यह काँच को नहीं भिगोता: इसका संपर्क कोण 90° से अधिक है।', 'ಅದು ಗಾಜನ್ನು ತೇವಗೊಳಿಸುವುದಿಲ್ಲ: ಅದರ ಸಂಪರ್ಕ ಕೋನ 90° ಗಿಂತ ಹೆಚ್ಚು.')),
              Q(W('Give an example of capillary action in daily life.', 'दैनिक जीवन में केशिका क्रिया का एक उदाहरण दें।', 'ದೈನಂದಿನ ಜೀವನದಲ್ಲಿ ಲೋಮನಾಳ ಕ್ರಿಯೆಯ ಒಂದು ಉದಾಹರಣೆ ಕೊಡಿ.'), W('Oil rising in a lamp wick; ink in blotting paper.', 'दीये की बत्ती में तेल का चढ़ना; सोख्ते में स्याही।', 'ದೀಪದ ಬತ್ತಿಯಲ್ಲಿ ಎಣ್ಣೆ ಏರುವುದು; ಒತ್ತುಕಾಗದದಲ್ಲಿ ಶಾಯಿ.')),
              Q(W('What is the unit of surface tension?', 'पृष्ठ तनाव का मात्रक क्या है?', 'ಮೇಲ್ಮೈ ಒತ್ತಡದ ಏಕಮಾನ ಯಾವುದು?'), W('N/m (or J/m²).', 'N/m (या J/m²).', 'N/m (ಅಥವಾ J/m²).'))])

    lab(id='newtons-law-cooling', bench='cooling', levels=[11], **mech,
        keywords=["newton's law of cooling", 'cooling', 'thermal properties of matter', 'heat', 'temperature'],
        title=W("Newton's law of cooling", 'न्यूटन का शीतलन नियम', 'ನ್ಯೂಟನ್‌ನ ತಂಪಾಗುವ ನಿಯಮ'),
        summary=W('Record the temperature of hot water as it cools and show that the rate of cooling depends on the excess temperature.', 'ठंडे होते गरम पानी का ताप लिखें और दिखाएँ कि शीतलन की दर अधिक ताप पर निर्भर करती है।', 'ತಣ್ಣಗಾಗುತ್ತಿರುವ ಬಿಸಿ ನೀರಿನ ತಾಪ ದಾಖಲಿಸಿ, ತಂಪಾಗುವ ದರ ಹೆಚ್ಚುವರಿ ತಾಪವನ್ನು ಅವಲಂಬಿಸಿದೆ ಎಂದು ತೋರಿಸಿ.'),
        aim=W('To study the relationship between the temperature of a hot body and time by plotting a cooling curve.', 'शीतलन वक्र बनाकर गरम वस्तु के ताप और समय के बीच संबंध का अध्ययन करना।', 'ತಂಪಾಗುವ ವಕ್ರ ಎಳೆದು ಬಿಸಿ ವಸ್ತುವಿನ ತಾಪ ಮತ್ತು ಸಮಯದ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('For small temperature differences the rate of loss of heat is proportional to the excess temperature over the surroundings: dT/dt = −k(T − T₀). So T − T₀ falls exponentially and ln(T − T₀) against t is a straight line of slope −k.', 'छोटे ताप अंतर के लिए ऊष्मा हानि की दर परिवेश से अधिक ताप के अनुक्रमानुपाती है: dT/dt = −k(T − T₀). इसलिए T − T₀ चरघातांकी रूप से घटता है और ln(T − T₀) तथा t का ग्राफ़ −k प्रवणता की सीधी रेखा है।', 'ಸಣ್ಣ ತಾಪ ವ್ಯತ್ಯಾಸಗಳಿಗೆ ಉಷ್ಣ ನಷ್ಟದ ದರ ಪರಿಸರಕ್ಕಿಂತ ಹೆಚ್ಚುವರಿ ತಾಪಕ್ಕೆ ಅನುಪಾತೀಯ: dT/dt = −k(T − T₀). ಆದ್ದರಿಂದ T − T₀ ಘಾತೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ; ln(T − T₀) ಮತ್ತು t ನಕ್ಷೆ −k ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ.'),
        apparatus=[W('Copper calorimeter with stirrer', 'विलोडक सहित ताँबे का कैलोरीमीटर', 'ಕಲಕಿ ಸಹಿತ ತಾಮ್ರದ ಕ್ಯಾಲೊರಿಮೀಟರ್'), W('Two thermometers (0.5 °C)', 'दो तापमापी (0.5 °C)', 'ಎರಡು ತಾಪಮಾಪಕಗಳು (0.5 °C)'), W('Hot water', 'गरम पानी', 'ಬಿಸಿ ನೀರು'), STOPWATCH],
        steps=[W('Note the room temperature T₀.', 'कमरे का ताप T₀ लिखें।', 'ಕೋಣೆಯ ತಾಪ T₀ ಬರೆಯಿರಿ.'),
               W('Fill the calorimeter with water at about 80 °C and start the stopwatch.', 'कैलोरीमीटर में लगभग 80 °C का पानी भरकर विराम घड़ी चालू करें।', 'ಕ್ಯಾಲೊರಿಮೀಟರ್‌ಗೆ ಸುಮಾರು 80 °C ನೀರು ತುಂಬಿ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ.'),
               W('Stir gently and record the temperature every minute for 20–30 minutes.', 'धीरे-धीरे हिलाते हुए 20–30 मिनट तक हर मिनट ताप लिखें।', 'ನಿಧಾನವಾಗಿ ಕಲಕುತ್ತಾ 20–30 ನಿಮಿಷ ಪ್ರತಿ ನಿಮಿಷ ತಾಪ ದಾಖಲಿಸಿ.'),
               W('Plot T against t (the cooling curve) and ln(T − T₀) against t.', 'T और t (शीतलन वक्र) तथा ln(T − T₀) और t के ग्राफ़ बनाएँ।', 'T ಮತ್ತು t (ತಂಪಾಗುವ ವಕ್ರ) ಹಾಗೂ ln(T − T₀) ಮತ್ತು t ನಕ್ಷೆಗಳನ್ನು ಎಳೆಯಿರಿ.'),
               W('Repeat with the calorimeter lagged and compare the slopes.', 'आवरणयुक्त कैलोरीमीटर के साथ दोहराएँ और प्रवणताओं की तुलना करें।', 'ಹೊದಿಕೆಯುಳ್ಳ ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಇಳಿಜಾರುಗಳನ್ನು ಹೋಲಿಸಿ.')],
        precautions=[W('Keep the calorimeter away from draughts and the sun.', 'कैलोरीमीटर को हवा के झोंकों और धूप से दूर रखें।', 'ಕ್ಯಾಲೊರಿಮೀಟರನ್ನು ಗಾಳಿ ಬೀಸು ಮತ್ತು ಬಿಸಿಲಿನಿಂದ ದೂರವಿಡಿ.'), W('Stir before each reading.', 'हर पाठ्यांक से पहले हिलाएँ।', 'ಪ್ರತಿ ಓದಿನ ಮೊದಲು ಕಲಕಿ.'), W('Do not let the thermometer touch the bottom.', 'तापमापी को तली से न छूने दें।', 'ತಾಪಮಾಪಕ ತಳ ಮುಟ್ಟದಿರಲಿ.')],
        conclusion=W('The water cools fast at first and slower as it nears room temperature; ln(T − T₀) falls linearly with time, as Newton’s law of cooling predicts. Lagging lowers k.', 'पानी पहले तेज़ी से और कमरे के ताप के पास आते हुए धीरे ठंडा होता है; ln(T − T₀) समय के साथ रैखिक रूप से घटता है, जैसा न्यूटन का शीतलन नियम बताता है। आवरण k को घटाता है।', 'ನೀರು ಮೊದಲು ವೇಗವಾಗಿ, ಕೋಣೆಯ ತಾಪ ಸಮೀಪಿಸಿದಂತೆ ನಿಧಾನವಾಗಿ ತಣ್ಣಗಾಗುತ್ತದೆ; ನ್ಯೂಟನ್ ನಿಯಮ ಹೇಳುವಂತೆ ln(T − T₀) ಸಮಯದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ. ಹೊದಿಕೆ k ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.'),
        viva=[Q(W('Why does hot tea cool quickly at first?', 'गरम चाय पहले जल्दी क्यों ठंडी होती है?', 'ಬಿಸಿ ಚಹಾ ಮೊದಲು ಬೇಗ ಏಕೆ ತಣ್ಣಗಾಗುತ್ತದೆ?'), W('Its excess temperature, and so its rate of heat loss, is largest then.', 'तब उसका अधिक ताप, और इसलिए ऊष्मा हानि की दर, सबसे अधिक होती है।', 'ಆಗ ಅದರ ಹೆಚ್ಚುವರಿ ತಾಪ, ಆದ್ದರಿಂದ ಉಷ್ಣ ನಷ್ಟದ ದರ, ಗರಿಷ್ಠ.')),
              Q(W('When does Newton’s law of cooling fail?', 'न्यूटन का शीतलन नियम कब लागू नहीं होता?', 'ನ್ಯೂಟನ್‌ನ ತಂಪಾಗುವ ನಿಯಮ ಯಾವಾಗ ವಿಫಲ?'), W('For large temperature differences, or when convection is forced.', 'बड़े ताप अंतर पर, या जब संवहन बलपूर्वक हो।', 'ದೊಡ್ಡ ತಾಪ ವ್ಯತ್ಯಾಸಗಳಲ್ಲಿ, ಅಥವಾ ಬಲವಂತದ ಸಂವಹನದಲ್ಲಿ.')),
              Q(W('How does the cooling rate depend on the surface?', 'शीतलन दर सतह पर कैसे निर्भर करती है?', 'ತಂಪಾಗುವ ದರ ಮೇಲ್ಮೈಯನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ?'), W('It grows with surface area and is larger for a dull, black surface.', 'यह सतह क्षेत्रफल के साथ बढ़ती है और खुरदरी, काली सतह के लिए अधिक है।', 'ಅದು ಮೇಲ್ಮೈ ವಿಸ್ತೀರ್ಣದೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ; ಮಸುಕಾದ, ಕಪ್ಪು ಮೇಲ್ಮೈಗೆ ಹೆಚ್ಚು.'))])

    lab(id='resonance-tube', bench='resonance-tube', levels=[11], **mech,
        keywords=['resonance tube', 'speed of sound', 'waves', 'resonance', 'end correction', 'tuning fork', 'sound'],
        title=W('Speed of sound with a resonance tube', 'अनुनाद नली से ध्वनि की चाल', 'ಅನುನಾದ ನಳಿಕೆಯಿಂದ ಧ್ವನಿಯ ವೇಗ'),
        summary=W('Lower the water in a tube under a tuning fork and find the two lengths where the sound is loudest.', 'स्वरित्र के नीचे नली में पानी घटाएँ और वे दो लंबाइयाँ ढूँढें जहाँ ध्वनि सबसे तेज़ हो।', 'ಶ್ರುತಿಕವೆಯ ಕೆಳಗೆ ನಳಿಕೆಯಲ್ಲಿ ನೀರನ್ನು ಇಳಿಸಿ, ಧ್ವನಿ ಅತಿ ಜೋರಾಗುವ ಎರಡು ಉದ್ದಗಳನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To find the speed of sound in air at room temperature using a resonance tube with two resonance positions, and the end correction.', 'दो अनुनाद स्थितियों द्वारा अनुनाद नली से कमरे के ताप पर वायु में ध्वनि की चाल और सिरा संशोधन ज्ञात करना।', 'ಎರಡು ಅನುನಾದ ಸ್ಥಾನಗಳ ಮೂಲಕ ಅನುನಾದ ನಳಿಕೆಯಿಂದ ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಗಾಳಿಯಲ್ಲಿ ಧ್ವನಿಯ ವೇಗ ಮತ್ತು ತುದಿ ತಿದ್ದುಪಡಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('An air column closed at one end resonates when its length plus the end correction is λ/4, 3λ/4, …: L₁ + e = λ/4 and L₂ + e = 3λ/4. Subtracting, λ = 2(L₂ − L₁) and v = fλ = 2f(L₂ − L₁); the end correction is e = (L₂ − 3L₁) ÷ 2 (about 0.3 × the diameter).', 'एक सिरे पर बंद वायु स्तंभ तब अनुनाद करता है जब उसकी लंबाई और सिरा संशोधन का योग λ/4, 3λ/4, … हो: L₁ + e = λ/4 और L₂ + e = 3λ/4. घटाने पर λ = 2(L₂ − L₁) और v = fλ = 2f(L₂ − L₁); सिरा संशोधन e = (L₂ − 3L₁) ÷ 2 (व्यास का लगभग 0.3 गुना)।', 'ಒಂದು ತುದಿ ಮುಚ್ಚಿದ ಗಾಳಿ ಸ್ತಂಭ ಅದರ ಉದ್ದ ಮತ್ತು ತುದಿ ತಿದ್ದುಪಡಿಯ ಮೊತ್ತ λ/4, 3λ/4, … ಆದಾಗ ಅನುನಾದಿಸುತ್ತದೆ: L₁ + e = λ/4, L₂ + e = 3λ/4. ಕಳೆದಾಗ λ = 2(L₂ − L₁), v = fλ = 2f(L₂ − L₁); ತುದಿ ತಿದ್ದುಪಡಿ e = (L₂ − 3L₁) ÷ 2 (ವ್ಯಾಸದ ಸುಮಾರು 0.3 ಪಟ್ಟು).'),
        apparatus=[W('Resonance tube with water reservoir', 'जल भंडार सहित अनुनाद नली', 'ನೀರಿನ ತೊಟ್ಟಿ ಸಹಿತ ಅನುನಾದ ನಳಿಕೆ'), W('Tuning forks of known frequency', 'ज्ञात आवृत्ति के स्वरित्र', 'ತಿಳಿದ ಆವರ್ತನದ ಶ್ರುತಿಕವೆಗಳು'), W('Rubber pad', 'रबर पैड', 'ರಬ್ಬರ್ ಪ್ಯಾಡ್'), W('Thermometer', 'तापमापी', 'ತಾಪಮಾಪಕ')],
        steps=[W('Fill the tube nearly to the top. Strike the fork on the rubber pad and hold it over the mouth.', 'नली को लगभग ऊपर तक भरें। स्वरित्र को रबर पैड पर मारकर मुँह के ऊपर पकड़ें।', 'ನಳಿಕೆಯನ್ನು ಬಹುತೇಕ ಮೇಲಿನವರೆಗೆ ತುಂಬಿ. ಶ್ರುತಿಕವೆಯನ್ನು ರಬ್ಬರ್ ಪ್ಯಾಡ್‌ಗೆ ಹೊಡೆದು ಬಾಯಿಯ ಮೇಲೆ ಹಿಡಿಯಿರಿ.'),
               W('Lower the water slowly until the sound is loudest; record the air column length L₁.', 'पानी धीरे-धीरे घटाएँ जब तक ध्वनि सबसे तेज़ न हो; वायु स्तंभ की लंबाई L₁ लिखें।', 'ಧ್ವನಿ ಅತಿ ಜೋರಾಗುವವರೆಗೆ ನೀರನ್ನು ನಿಧಾನವಾಗಿ ಇಳಿಸಿ; ಗಾಳಿ ಸ್ತಂಭದ ಉದ್ದ L₁ ದಾಖಲಿಸಿ.'),
               W('Lower it further to the second loud position, about three times as long: L₂.', 'उसे और नीचे लगभग तिगुनी लंबाई वाली दूसरी तेज़ स्थिति तक ले जाएँ: L₂.', 'ಸುಮಾರು ಮೂರು ಪಟ್ಟು ಉದ್ದದ ಎರಡನೇ ಜೋರು ಸ್ಥಾನಕ್ಕೆ ಇನ್ನೂ ಇಳಿಸಿ: L₂.'),
               W('Approach each position from above and below and take the mean.', 'हर स्थिति तक ऊपर और नीचे दोनों ओर से पहुँचकर माध्य लें।', 'ಪ್ರತಿ ಸ್ಥಾನವನ್ನು ಮೇಲಿನಿಂದ ಮತ್ತು ಕೆಳಗಿನಿಂದ ತಲುಪಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ.'),
               W('Work out v = 2f(L₂ − L₁) and e for each fork.', 'हर स्वरित्र के लिए v = 2f(L₂ − L₁) और e निकालें।', 'ಪ್ರತಿ ಶ್ರುತಿಕವೆಗೆ v = 2f(L₂ − L₁) ಮತ್ತು e ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Do not let the vibrating fork touch the tube.', 'कंपित स्वरित्र को नली से न छूने दें।', 'ಕಂಪಿಸುವ ಶ್ರುತಿಕವೆ ನಳಿಕೆಯನ್ನು ಮುಟ್ಟದಿರಲಿ.'), W('Strike the fork on rubber, never on a hard surface.', 'स्वरित्र को रबर पर मारें, कठोर सतह पर कभी नहीं।', 'ಶ್ರುತಿಕವೆಯನ್ನು ರಬ್ಬರ್ ಮೇಲೆ ಹೊಡೆಯಿರಿ, ಗಟ್ಟಿ ಮೇಲ್ಮೈ ಮೇಲೆ ಎಂದೂ ಅಲ್ಲ.'), W('Read the bottom of the water meniscus.', 'पानी के मेनिस्कस का निचला तल पढ़ें।', 'ನೀರಿನ ಮೆನಿಸ್ಕಸ್‌ನ ತಳವನ್ನು ಓದಿ.')],
        conclusion=W('L₂ is about three times L₁, and v = 2f(L₂ − L₁) gives the speed of sound close to 346 m/s at 25 °C, independent of the fork used.', 'L₂ लगभग L₁ का तिगुना है, और v = 2f(L₂ − L₁) से 25 °C पर ध्वनि की चाल लगभग 346 m/s मिलती है, जो प्रयुक्त स्वरित्र पर निर्भर नहीं करती।', 'L₂ ಸುಮಾರು L₁ ನ ಮೂರು ಪಟ್ಟು; v = 2f(L₂ − L₁) 25 °C ನಲ್ಲಿ ಧ್ವನಿಯ ವೇಗವನ್ನು ಸುಮಾರು 346 m/s ಆಗಿ ನೀಡುತ್ತದೆ, ಬಳಸಿದ ಶ್ರುತಿಕವೆಯನ್ನು ಅವಲಂಬಿಸದೆ.'),
        viva=[Q(W('Why is the second resonance length not exactly 3L₁?', 'दूसरी अनुनाद लंबाई ठीक 3L₁ क्यों नहीं होती?', 'ಎರಡನೇ ಅನುನಾದ ಉದ್ದ ನಿಖರವಾಗಿ 3L₁ ಏಕೆ ಅಲ್ಲ?'), W('Because of the end correction: the antinode forms a little above the open end.', 'सिरा संशोधन के कारण: प्रस्पंद खुले सिरे से थोड़ा ऊपर बनता है।', 'ತುದಿ ತಿದ್ದುಪಡಿಯಿಂದ: ಪ್ರಸ್ಪಂದ ತೆರೆದ ತುದಿಯ ಸ್ವಲ್ಪ ಮೇಲೆ ಮೂಡುತ್ತದೆ.')),
              Q(W('How does the speed of sound change with temperature?', 'ताप के साथ ध्वनि की चाल कैसे बदलती है?', 'ತಾಪದೊಂದಿಗೆ ಧ್ವನಿಯ ವೇಗ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?'), W('It increases, by about 0.6 m/s per °C.', 'यह बढ़ती है, लगभग 0.6 m/s प्रति °C.', 'ಅದು ಹೆಚ್ಚುತ್ತದೆ, ಪ್ರತಿ °C ಗೆ ಸುಮಾರು 0.6 m/s.')),
              Q(W('What is at the water surface: a node or an antinode?', 'पानी की सतह पर निस्पंद है या प्रस्पंद?', 'ನೀರಿನ ಮೇಲ್ಮೈಯಲ್ಲಿ ನಿಸ್ಪಂದವೇ ಪ್ರಸ್ಪಂದವೇ?'), W('A displacement node (the air cannot move there).', 'एक विस्थापन निस्पंद (वहाँ वायु हिल नहीं सकती)।', 'ಸ್ಥಳಾಂತರ ನಿಸ್ಪಂದ (ಅಲ್ಲಿ ಗಾಳಿ ಚಲಿಸಲಾರದು).'))])

    # ------------------------------------------------------- modern (UG)
    ug = dict(subject='Physics', domain='physics', levels=['ug'], curricula=['ug-physics'])
    lab(id='e-by-m', bench='e-by-m', **ug,
        keywords=['e/m', 'specific charge', 'electron', 'helmholtz coils', 'fine beam tube', 'magnetic field', 'modern physics'],
        title=W('e/m of the electron (fine-beam tube)', 'इलेक्ट्रॉन का e/m (सूक्ष्म-किरण नली)', 'ಎಲೆಕ್ಟ್ರಾನ್‌ನ e/m (ಸೂಕ್ಷ್ಮ-ಕಿರಣ ನಳಿಕೆ)'),
        summary=W('Bend an electron beam into a circle with Helmholtz coils and work out e/m from V, B and r.', 'हेल्महोल्ट्ज़ कुंडलियों से इलेक्ट्रॉन किरण को वृत्त में मोड़ें और V, B और r से e/m निकालें।', 'ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳಿಂದ ಎಲೆಕ್ಟ್ರಾನ್ ಕಿರಣವನ್ನು ವೃತ್ತವಾಗಿ ಬಾಗಿಸಿ V, B ಮತ್ತು r ನಿಂದ e/m ಲೆಕ್ಕಿಸಿ.'),
        aim=W('To find the specific charge e/m of the electron.', 'इलेक्ट्रॉन का विशिष्ट आवेश e/m ज्ञात करना।', 'ಎಲೆಕ್ಟ್ರಾನ್‌ನ ವಿಶಿಷ್ಟ ಆವೇಶ e/m ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Electrons accelerated through V gain ½mv² = eV. In a uniform field B at right angles they move in a circle with evB = mv²/r. Eliminating v, e/m = 2V ÷ (B²r²). The Helmholtz coils give B = (4/5)^(3/2) μ₀NI ÷ R.', 'V से त्वरित इलेक्ट्रॉन ½mv² = eV पाते हैं। समकोण पर एकसमान क्षेत्र B में वे evB = mv²/r के साथ वृत्त में चलते हैं। v हटाने पर e/m = 2V ÷ (B²r²). हेल्महोल्ट्ज़ कुंडलियाँ B = (4/5)^(3/2) μ₀NI ÷ R देती हैं।', 'V ಮೂಲಕ ವೇಗವರ್ಧಿತ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ½mv² = eV ಪಡೆಯುತ್ತವೆ. ಲಂಬವಾದ ಏಕರೂಪ ಕ್ಷೇತ್ರ B ಯಲ್ಲಿ ಅವು evB = mv²/r ನೊಂದಿಗೆ ವೃತ್ತದಲ್ಲಿ ಚಲಿಸುತ್ತವೆ. v ತೆಗೆದರೆ e/m = 2V ÷ (B²r²). ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳು B = (4/5)^(3/2) μ₀NI ÷ R ನೀಡುತ್ತವೆ.'),
        apparatus=[W('Fine-beam tube with a radius scale', 'त्रिज्या पैमाने सहित सूक्ष्म-किरण नली', 'ತ್ರಿಜ್ಯ ಅಳತೆ ಸಹಿತ ಸೂಕ್ಷ್ಮ-ಕಿರಣ ನಳಿಕೆ'), W('Helmholtz coils (130 turns, R = 15 cm)', 'हेल्महोल्ट्ज़ कुंडलियाँ (130 फेरे, R = 15 cm)', 'ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳು (130 ಸುತ್ತು, R = 15 cm)'), W('High-voltage supply (0–300 V) and coil supply', 'उच्च वोल्टता आपूर्ति (0–300 V) और कुंडली आपूर्ति', 'ಹೆಚ್ಚಿನ ವೋಲ್ಟೇಜ್ ಪೂರೈಕೆ (0–300 V) ಮತ್ತು ಸುರುಳಿ ಪೂರೈಕೆ'), W('Ammeter and voltmeter', 'ऐमीटर और वोल्टमीटर', 'ಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್')],
        steps=[W('Darken the room, warm the filament and set an accelerating voltage.', 'कमरे में अँधेरा करें, तंतु गरम करें और त्वरक वोल्टता तय करें।', 'ಕೋಣೆಯನ್ನು ಕತ್ತಲಾಗಿಸಿ, ತಂತು ಬಿಸಿಮಾಡಿ ವೇಗವರ್ಧಕ ವೋಲ್ಟೇಜ್ ಹೊಂದಿಸಿ.'),
               W('Raise the coil current until the beam closes into a circle; read its radius on the scale.', 'कुंडली धारा बढ़ाएँ जब तक किरण वृत्त में बंद न हो जाए; पैमाने पर उसकी त्रिज्या पढ़ें।', 'ಕಿರಣ ವೃತ್ತವಾಗಿ ಮುಚ್ಚುವವರೆಗೆ ಸುರುಳಿ ಪ್ರವಾಹ ಹೆಚ್ಚಿಸಿ; ಅಳತೆಯ ಮೇಲೆ ಅದರ ತ್ರಿಜ್ಯ ಓದಿ.'),
               W('Record V, I and r; compute B and e/m.', 'V, I और r लिखें; B और e/m निकालें।', 'V, I ಮತ್ತು r ದಾಖಲಿಸಿ; B ಮತ್ತು e/m ಲೆಕ್ಕಿಸಿ.'),
               W('Repeat for several voltages and currents and find the mean with its standard error.', 'कई वोल्टताओं और धाराओं के लिए दोहराएँ और मानक त्रुटि सहित माध्य निकालें।', 'ಹಲವು ವೋಲ್ಟೇಜ್ ಮತ್ತು ಪ್ರವಾಹಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಪ್ರಮಾಣಿತ ದೋಷ ಸಹಿತ ಸರಾಸರಿ ಪಡೆಯಿರಿ.'), CSV],
        precautions=[W('High voltage: switch off before touching any connection.', 'उच्च वोल्टता: किसी भी संयोजन को छूने से पहले बंद करें।', 'ಹೆಚ್ಚಿನ ವೋಲ್ಟೇಜ್: ಯಾವುದೇ ಸಂಪರ್ಕ ಮುಟ್ಟುವ ಮೊದಲು ಆಫ್ ಮಾಡಿ.'), W('Read the radius without parallax, using the scale inside the tube.', 'नली के भीतर के पैमाने से बिना लंबन के त्रिज्या पढ़ें।', 'ನಳಿಕೆಯೊಳಗಿನ ಅಳತೆಯಿಂದ ಭ್ರಂಶವಿಲ್ಲದೆ ತ್ರಿಜ್ಯ ಓದಿ.'), W('Keep magnetic objects away; the Earth’s field adds a small error.', 'चुंबकीय वस्तुएँ दूर रखें; पृथ्वी का क्षेत्र छोटी त्रुटि जोड़ता है।', 'ಕಾಂತೀಯ ವಸ್ತುಗಳನ್ನು ದೂರವಿಡಿ; ಭೂಮಿಯ ಕ್ಷೇತ್ರ ಸಣ್ಣ ದೋಷ ಸೇರಿಸುತ್ತದೆ.')],
        conclusion=W('The specific charge of the electron comes out close to 1.76 × 10¹¹ C/kg, independent of V and B.', 'इलेक्ट्रॉन का विशिष्ट आवेश V और B से स्वतंत्र, 1.76 × 10¹¹ C/kg के निकट आता है।', 'ಎಲೆಕ್ಟ್ರಾನ್‌ನ ವಿಶಿಷ್ಟ ಆವೇಶ V ಮತ್ತು B ಯನ್ನು ಅವಲಂಬಿಸದೆ 1.76 × 10¹¹ C/kg ಹತ್ತಿರ ಬರುತ್ತದೆ.'),
        viva=[Q(W('Why does the beam glow?', 'किरण क्यों चमकती है?', 'ಕಿರಣ ಏಕೆ ಹೊಳೆಯುತ್ತದೆ?'), W('Electrons excite the low-pressure gas, which gives out light.', 'इलेक्ट्रॉन निम्न दाब की गैस को उत्तेजित करते हैं, जो प्रकाश देती है।', 'ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ಕಡಿಮೆ ಒತ್ತಡದ ಅನಿಲವನ್ನು ಉದ್ರೇಕಿಸುತ್ತವೆ, ಅದು ಬೆಳಕು ನೀಡುತ್ತದೆ.')),
              Q(W('Does the magnetic force change the electrons’ speed?', 'क्या चुंबकीय बल इलेक्ट्रॉनों की चाल बदलता है?', 'ಕಾಂತೀಯ ಬಲ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳ ವೇಗ ಬದಲಿಸುತ್ತದೆಯೇ?'), W('No; it is always at right angles to the velocity and only changes direction.', 'नहीं; यह सदा वेग के लंबवत होता है और केवल दिशा बदलता है।', 'ಇಲ್ಲ; ಅದು ಯಾವಾಗಲೂ ವೇಗಕ್ಕೆ ಲಂಬವಾಗಿದ್ದು ದಿಕ್ಕನ್ನು ಮಾತ್ರ ಬದಲಿಸುತ್ತದೆ.')),
              Q(W('Who first measured e/m?', 'e/m सबसे पहले किसने मापा?', 'e/m ಅನ್ನು ಮೊದಲು ಯಾರು ಅಳೆದರು?'), W('J. J. Thomson, in 1897.', 'जे. जे. टॉमसन ने, 1897 में।', 'ಜೆ. ಜೆ. ಥಾಮ್ಸನ್, 1897 ರಲ್ಲಿ.'))])

    lab(id='photoelectric-effect', bench='photoelectric', subject='Physics', domain='physics', levels=[12, 'ug'], curricula=['ug-physics', 'cbse'],
        keywords=['photoelectric effect', 'stopping potential', 'work function', "planck's constant", 'dual nature of radiation and matter', 'threshold frequency'],
        title=W("Photoelectric effect: Planck's constant and work function", 'प्रकाश-विद्युत प्रभाव: प्लांक नियतांक और कार्य फलन', 'ದ್ಯುತಿವಿದ್ಯುತ್ ಪರಿಣಾಮ: ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ಮತ್ತು ಕಾರ್ಯ ಫಲನ'),
        summary=W('Find the stopping potential for light of several colours; its slope against frequency gives h, its intercept the work function.', 'कई रंगों के प्रकाश के लिए निरोधी विभव ज्ञात करें; आवृत्ति के सापेक्ष उसकी प्रवणता h और अंतःखंड कार्य फलन देता है।', 'ಹಲವು ಬಣ್ಣಗಳ ಬೆಳಕಿಗೆ ನಿಲುಗಡೆ ವಿಭವ ಕಂಡುಹಿಡಿಯಿರಿ; ಆವರ್ತನದ ವಿರುದ್ಧ ಅದರ ಇಳಿಜಾರು h, ಅಂತಃಖಂಡ ಕಾರ್ಯ ಫಲನ ನೀಡುತ್ತದೆ.'),
        aim=W("To study the photoelectric effect and find Planck's constant and the work function of the cathode.", 'प्रकाश-विद्युत प्रभाव का अध्ययन कर प्लांक नियतांक और कैथोड का कार्य फलन ज्ञात करना।', 'ದ್ಯುತಿವಿದ್ಯುತ್ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡಿ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ಮತ್ತು ಕ್ಯಾಥೋಡ್‌ನ ಕಾರ್ಯ ಫಲನ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Light comes in photons of energy hν. An electron that absorbs one leaves the metal with at most hν − φ of kinetic energy, and a retarding potential V₀ = (h/e)ν − φ/e just stops it (Einstein’s equation). Brighter light gives more electrons, not faster ones.', 'प्रकाश hν ऊर्जा के फ़ोटॉनों में आता है। एक फ़ोटॉन सोखने वाला इलेक्ट्रॉन अधिकतम hν − φ गतिज ऊर्जा से धातु छोड़ता है, और निरोधी विभव V₀ = (h/e)ν − φ/e उसे ठीक रोक देता है (आइंस्टीन समीकरण)। तेज़ प्रकाश अधिक इलेक्ट्रॉन देता है, तेज़ नहीं।', 'ಬೆಳಕು hν ಶಕ್ತಿಯ ಫೋಟಾನ್‌ಗಳಾಗಿ ಬರುತ್ತದೆ. ಒಂದನ್ನು ಹೀರಿದ ಎಲೆಕ್ಟ್ರಾನ್ ಗರಿಷ್ಠ hν − φ ಚಲನ ಶಕ್ತಿಯೊಂದಿಗೆ ಲೋಹ ಬಿಡುತ್ತದೆ; ನಿಲುಗಡೆ ವಿಭವ V₀ = (h/e)ν − φ/e ಅದನ್ನು ನಿಲ್ಲಿಸುತ್ತದೆ (ಐನ್‌ಸ್ಟೈನ್ ಸಮೀಕರಣ). ಪ್ರಕಾಶಮಾನ ಬೆಳಕು ಹೆಚ್ಚು ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳನ್ನು ನೀಡುತ್ತದೆ, ವೇಗದವಲ್ಲ.'),
        apparatus=[W('Vacuum photocell', 'निर्वात प्रकाश-सेल', 'ನಿರ್ವಾತ ದ್ಯುತಿಕೋಶ'), W('Mercury lamp with colour filters', 'रंग फ़िल्टरों सहित पारद लैंप', 'ಬಣ್ಣದ ಫಿಲ್ಟರ್‌ಗಳ ಸಹಿತ ಪಾದರಸ ದೀಪ'), W('Variable retarding/accelerating voltage supply', 'परिवर्ती निरोधी/त्वरक वोल्टता आपूर्ति', 'ಬದಲಾಯಿಸಬಹುದಾದ ನಿಲುಗಡೆ/ವೇಗವರ್ಧಕ ವೋಲ್ಟೇಜ್ ಪೂರೈಕೆ'), W('Nanoammeter and voltmeter', 'नैनोऐमीटर और वोल्टमीटर', 'ನ್ಯಾನೋಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್')],
        steps=[W('Put a filter in front of the photocell and switch on the lamp.', 'प्रकाश-सेल के सामने एक फ़िल्टर लगाएँ और लैंप चालू करें।', 'ದ್ಯುತಿಕೋಶದ ಮುಂದೆ ಒಂದು ಫಿಲ್ಟರ್ ಇಟ್ಟು ದೀಪ ಆನ್ ಮಾಡಿ.'),
               W('Record the photocurrent as you make the anode more and more negative.', 'ऐनोड को अधिकाधिक ऋणात्मक करते हुए प्रकाश-धारा लिखें।', 'ಆನೋಡನ್ನು ಹೆಚ್ಚು ಹೆಚ್ಚು ಋಣಗೊಳಿಸುತ್ತಾ ದ್ಯುತಿ ಪ್ರವಾಹ ದಾಖಲಿಸಿ.'),
               W('Note the stopping potential V₀ where the current just becomes zero.', 'वह निरोधी विभव V₀ लिखें जहाँ धारा ठीक शून्य हो जाती है।', 'ಪ್ರವಾಹ ಕೇವಲ ಶೂನ್ಯವಾಗುವ ನಿಲುಗಡೆ ವಿಭವ V₀ ಬರೆಯಿರಿ.'),
               W('Repeat for each filter, and for one filter at half intensity.', 'हर फ़िल्टर के लिए, और एक फ़िल्टर के लिए आधी तीव्रता पर, दोहराएँ।', 'ಪ್ರತಿ ಫಿಲ್ಟರ್‌ಗೆ, ಮತ್ತು ಒಂದು ಫಿಲ್ಟರ್‌ಗೆ ಅರ್ಧ ತೀವ್ರತೆಯಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Plot V₀ against ν: h = e × slope, φ = −e × intercept.', 'V₀ और ν का ग्राफ़ बनाएँ: h = e × प्रवणता, φ = −e × अंतःखंड।', 'V₀ ಮತ್ತು ν ನಕ್ಷೆ ಎಳೆಯಿರಿ: h = e × ಇಳಿಜಾರು, φ = −e × ಅಂತಃಖಂಡ.'), CSV],
        precautions=[W('Shield the photocell from room light.', 'प्रकाश-सेल को कमरे के प्रकाश से बचाएँ।', 'ದ್ಯುತಿಕೋಶವನ್ನು ಕೋಣೆಯ ಬೆಳಕಿನಿಂದ ರಕ್ಷಿಸಿ.'), W('Do not look at the mercury lamp: it emits ultraviolet.', 'पारद लैंप की ओर न देखें: यह पराबैंगनी उत्सर्जित करता है।', 'ಪಾದರಸ ದೀಪದತ್ತ ನೋಡಬೇಡಿ: ಅದು ಅತಿನೇರಳೆ ಹೊರಸೂಸುತ್ತದೆ.'), W('Approach the stopping potential slowly.', 'निरोधी विभव तक धीरे-धीरे पहुँचें।', 'ನಿಲುಗಡೆ ವಿಭವವನ್ನು ನಿಧಾನವಾಗಿ ಸಮೀಪಿಸಿ.')],
        conclusion=W('The stopping potential rises linearly with frequency and does not depend on intensity; the slope gives h ≈ 6.6 × 10⁻³⁴ J s and the intercept the work function of the cathode.', 'निरोधी विभव आवृत्ति के साथ रैखिक रूप से बढ़ता है और तीव्रता पर निर्भर नहीं करता; प्रवणता h ≈ 6.6 × 10⁻³⁴ J s और अंतःखंड कैथोड का कार्य फलन देता है।', 'ನಿಲುಗಡೆ ವಿಭವ ಆವರ್ತನದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಏರುತ್ತದೆ, ತೀವ್ರತೆಯನ್ನು ಅವಲಂಬಿಸುವುದಿಲ್ಲ; ಇಳಿಜಾರು h ≈ 6.6 × 10⁻³⁴ J s, ಅಂತಃಖಂಡ ಕ್ಯಾಥೋಡ್‌ನ ಕಾರ್ಯ ಫಲನ ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('What is the threshold frequency?', 'देहली आवृत्ति क्या है?', 'ಹೊಸ್ತಿಲು ಆವರ್ತನ ಎಂದರೇನು?'), W('The least frequency that can eject electrons: ν₀ = φ/h.', 'इलेक्ट्रॉन निकाल सकने वाली न्यूनतम आवृत्ति: ν₀ = φ/h.', 'ಎಲೆಕ್ಟ್ರಾನ್ ಹೊರಹಾಕಬಲ್ಲ ಕನಿಷ್ಠ ಆವರ್ತನ: ν₀ = φ/h.')),
              Q(W('Why does red light not eject electrons from zinc however bright it is?', 'लाल प्रकाश कितना भी तेज़ हो, जस्ते से इलेक्ट्रॉन क्यों नहीं निकालता?', 'ಕೆಂಪು ಬೆಳಕು ಎಷ್ಟೇ ಪ್ರಕಾಶಮಾನವಾಗಿದ್ದರೂ ಸತುವಿನಿಂದ ಎಲೆಕ್ಟ್ರಾನ್ ಏಕೆ ಹೊರಹಾಕುವುದಿಲ್ಲ?'), W('Each photon has less energy than the work function.', 'हर फ़ोटॉन की ऊर्जा कार्य फलन से कम है।', 'ಪ್ರತಿ ಫೋಟಾನ್‌ನ ಶಕ್ತಿ ಕಾರ್ಯ ಫಲನಕ್ಕಿಂತ ಕಡಿಮೆ.')),
              Q(W('What does the saturation current depend on?', 'संतृप्त धारा किस पर निर्भर करती है?', 'ಸಂತೃಪ್ತ ಪ್ರವಾಹ ಯಾವುದನ್ನು ಅವಲಂಬಿಸುತ್ತದೆ?'), W('The intensity of the light (number of photons per second).', 'प्रकाश की तीव्रता (प्रति सेकंड फ़ोटॉनों की संख्या) पर।', 'ಬೆಳಕಿನ ತೀವ್ರತೆ (ಪ್ರತಿ ಸೆಕೆಂಡಿಗೆ ಫೋಟಾನ್‌ಗಳ ಸಂಖ್ಯೆ).'))])

    lab(id='hall-effect', bench='hall', **ug,
        keywords=['hall effect', 'hall coefficient', 'carrier concentration', 'semiconductor', 'magnetic field', 'solid state physics'],
        title=W('Hall effect in a semiconductor', 'अर्धचालक में हॉल प्रभाव', 'ಅರೆವಾಹಕದಲ್ಲಿ ಹಾಲ್ ಪರಿಣಾಮ'),
        summary=W('Measure the Hall voltage across a slab in a magnetic field; get the carrier type and density.', 'चुंबकीय क्षेत्र में एक पट्टी के आर-पार हॉल वोल्टता मापें; वाहक का प्रकार और घनत्व ज्ञात करें।', 'ಕಾಂತ ಕ್ಷೇತ್ರದಲ್ಲಿ ಚಪ್ಪಡಿಯ ಅಡ್ಡಲಾಗಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಅಳೆಯಿರಿ; ವಾಹಕದ ಪ್ರಕಾರ ಮತ್ತು ಸಾಂದ್ರತೆ ಪಡೆಯಿರಿ.'),
        aim=W('To find the Hall coefficient, the type of charge carriers and their density in a semiconductor.', 'अर्धचालक का हॉल गुणांक, आवेश वाहकों का प्रकार और उनका घनत्व ज्ञात करना।', 'ಅರೆವಾಹಕದ ಹಾಲ್ ಗುಣಾಂಕ, ಆವೇಶ ವಾಹಕಗಳ ಪ್ರಕಾರ ಮತ್ತು ಅವುಗಳ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Charges moving through a slab in a perpendicular field B are pushed to one face until the electric field of the Hall voltage balances the magnetic force. V_H = IB ÷ (nqt), so R_H = V_H t ÷ (IB) = 1/(nq). Its sign tells whether the carriers are electrons or holes.', 'लंबवत क्षेत्र B में पट्टी से गुजरते आवेश एक सतह की ओर धकेले जाते हैं जब तक हॉल वोल्टता का विद्युत क्षेत्र चुंबकीय बल को संतुलित न कर दे। V_H = IB ÷ (nqt), अतः R_H = V_H t ÷ (IB) = 1/(nq). इसका चिह्न बताता है कि वाहक इलेक्ट्रॉन हैं या होल।', 'ಲಂಬ ಕ್ಷೇತ್ರ B ಯಲ್ಲಿ ಚಪ್ಪಡಿಯ ಮೂಲಕ ಚಲಿಸುವ ಆವೇಶಗಳು ಹಾಲ್ ವೋಲ್ಟೇಜ್‌ನ ವಿದ್ಯುತ್ ಕ್ಷೇತ್ರ ಕಾಂತೀಯ ಬಲವನ್ನು ಸಮತೋಲಿಸುವವರೆಗೆ ಒಂದು ಮುಖಕ್ಕೆ ತಳ್ಳಲ್ಪಡುತ್ತವೆ. V_H = IB ÷ (nqt); ಆದ್ದರಿಂದ R_H = V_H t ÷ (IB) = 1/(nq). ಅದರ ಚಿಹ್ನೆ ವಾಹಕಗಳು ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳೇ ರಂಧ್ರಗಳೇ ಎಂದು ತಿಳಿಸುತ್ತದೆ.'),
        apparatus=[W('Hall probe (germanium slab, 0.5 mm thick)', 'हॉल प्रोब (जर्मेनियम पट्टी, 0.5 mm मोटी)', 'ಹಾಲ್ ಪ್ರೋಬ್ (ಜರ್ಮೇನಿಯಂ ಚಪ್ಪಡಿ, 0.5 mm ದಪ್ಪ)'), W('Electromagnet with power supply', 'विद्युत आपूर्ति सहित विद्युत-चुंबक', 'ವಿದ್ಯುತ್ ಪೂರೈಕೆ ಸಹಿತ ವಿದ್ಯುತ್ಕಾಂತ'), W('Gaussmeter', 'गॉसमीटर', 'ಗಾಸ್‌ಮೀಟರ್'), W('Constant-current source and millivoltmeter', 'स्थिर-धारा स्रोत और मिलीवोल्टमीटर', 'ಸ್ಥಿರ-ಪ್ರವಾಹ ಮೂಲ ಮತ್ತು ಮಿಲಿವೋಲ್ಟ್‌ಮೀಟರ್')],
        steps=[W('Place the probe between the pole pieces with its face perpendicular to B. Measure B with the gaussmeter.', 'प्रोब को ध्रुव खंडों के बीच, उसकी सतह B के लंबवत रखें। गॉसमीटर से B मापें।', 'ಪ್ರೋಬನ್ನು ಧ್ರುವ ತುಂಡುಗಳ ನಡುವೆ, ಅದರ ಮುಖ B ಗೆ ಲಂಬವಾಗಿರುವಂತೆ ಇಡಿ. ಗಾಸ್‌ಮೀಟರ್‌ನಿಂದ B ಅಳೆಯಿರಿ.'),
               W('Pass a current through the slab and read the Hall voltage.', 'पट्टी से धारा प्रवाहित करें और हॉल वोल्टता पढ़ें।', 'ಚಪ್ಪಡಿಯ ಮೂಲಕ ಪ್ರವಾಹ ಹರಿಸಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಓದಿ.'),
               W('Vary the current at fixed B, then B at fixed current.', 'नियत B पर धारा बदलें, फिर नियत धारा पर B बदलें।', 'ಸ್ಥಿರ B ಯಲ್ಲಿ ಪ್ರವಾಹ ಬದಲಿಸಿ, ನಂತರ ಸ್ಥಿರ ಪ್ರವಾಹದಲ್ಲಿ B ಬದಲಿಸಿ.'),
               W('Plot V_H against I; find R_H, the sign of the carriers and n.', 'V_H और I का ग्राफ़ बनाएँ; R_H, वाहकों का चिह्न और n ज्ञात करें।', 'V_H ಮತ್ತು I ನಕ್ಷೆ ಎಳೆಯಿರಿ; R_H, ವಾಹಕಗಳ ಚಿಹ್ನೆ ಮತ್ತು n ಕಂಡುಹಿಡಿಯಿರಿ.'), CSV],
        precautions=[W('Do not exceed the rated probe current (it heats the slab).', 'प्रोब की निर्धारित धारा से अधिक न दें (पट्टी गरम होती है)।', 'ಪ್ರೋಬ್‌ನ ನಿಗದಿತ ಪ್ರವಾಹ ಮೀರಬೇಡಿ (ಚಪ್ಪಡಿ ಬಿಸಿಯಾಗುತ್ತದೆ).'), W('Reverse B and I to cancel the offset voltage.', 'ऑफ़सेट वोल्टता मिटाने के लिए B और I उलटें।', 'ಆಫ್‌ಸೆಟ್ ವೋಲ್ಟೇಜ್ ರದ್ದುಗೊಳಿಸಲು B ಮತ್ತು I ಹಿಮ್ಮುಖಗೊಳಿಸಿ.'), W('The probe is fragile: handle it gently.', 'प्रोब नाज़ुक है: उसे धीरे से संभालें।', 'ಪ್ರೋಬ್ ನಾಜೂಕು: ಮೃದುವಾಗಿ ನಿರ್ವಹಿಸಿ.')],
        conclusion=W('V_H is proportional to both I and B; the Hall coefficient gives the sign and density of the carriers (about 10²¹ m⁻³ in doped germanium).', 'V_H, I और B दोनों के अनुक्रमानुपाती है; हॉल गुणांक वाहकों का चिह्न और घनत्व (मादित जर्मेनियम में लगभग 10²¹ m⁻³) देता है।', 'V_H, I ಮತ್ತು B ಎರಡಕ್ಕೂ ಅನುಪಾತೀಯ; ಹಾಲ್ ಗುಣಾಂಕ ವಾಹಕಗಳ ಚಿಹ್ನೆ ಮತ್ತು ಸಾಂದ್ರತೆ (ಡೋಪ್ ಮಾಡಿದ ಜರ್ಮೇನಿಯಂನಲ್ಲಿ ಸುಮಾರು 10²¹ m⁻³) ನೀಡುತ್ತದೆ.'),
        viva=[Q(W('Why is the Hall voltage much larger in a semiconductor than in a metal?', 'अर्धचालक में हॉल वोल्टता धातु से बहुत अधिक क्यों होती है?', 'ಅರೆವಾಹಕದಲ್ಲಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಲೋಹಕ್ಕಿಂತ ಬಹಳ ಹೆಚ್ಚು ಏಕೆ?'), W('It has far fewer carriers, so they must drift faster to carry the same current.', 'उसमें वाहक बहुत कम होते हैं, इसलिए समान धारा के लिए उन्हें तेज़ बहना पड़ता है।', 'ಅದರಲ್ಲಿ ವಾಹಕಗಳು ಬಹಳ ಕಡಿಮೆ; ಅದೇ ಪ್ರವಾಹಕ್ಕೆ ಅವು ವೇಗವಾಗಿ ಹರಿಯಬೇಕು.')),
              Q(W('What is a Hall probe used for?', 'हॉल प्रोब किसके लिए प्रयोग होता है?', 'ಹಾಲ್ ಪ್ರೋಬನ್ನು ಯಾವುದಕ್ಕೆ ಬಳಸುತ್ತಾರೆ?'), W('To measure magnetic fields.', 'चुंबकीय क्षेत्र मापने के लिए।', 'ಕಾಂತ ಕ್ಷೇತ್ರಗಳನ್ನು ಅಳೆಯಲು.')),
              Q(W('What does a positive Hall coefficient mean?', 'धनात्मक हॉल गुणांक का क्या अर्थ है?', 'ಧನ ಹಾಲ್ ಗುಣಾಂಕದ ಅರ್ಥವೇನು?'), W('The majority carriers are holes (p-type).', 'बहुसंख्यक वाहक होल हैं (p-प्रकार)।', 'ಬಹುಸಂಖ್ಯಾತ ವಾಹಕಗಳು ರಂಧ್ರಗಳು (p-ಪ್ರಕಾರ).'))])

    lab(id='bh-curve', bench='bh-curve', **ug,
        keywords=['hysteresis', 'b-h curve', 'retentivity', 'coercivity', 'ferromagnetism', 'magnetism and matter'],
        title=W('B–H curve (hysteresis) of soft iron', 'नरम लोहे का B–H वक्र (शैथिल्य)', 'ಮೃದು ಕಬ್ಬಿಣದ B–H ವಕ್ರ (ಹಿಸ್ಟರಿಸಿಸ್)'),
        summary=W('Take the magnetising field up and down and trace the hysteresis loop; read retentivity and coercivity.', 'चुंबकन क्षेत्र को ऊपर-नीचे करके शैथिल्य पाश बनाएँ; धारणशीलता और निग्राहिता पढ़ें।', 'ಕಾಂತೀಕರಣ ಕ್ಷೇತ್ರವನ್ನು ಏರಿಸಿ-ಇಳಿಸಿ ಹಿಸ್ಟರಿಸಿಸ್ ಕುಣಿಕೆ ಎಳೆಯಿರಿ; ಧಾರಣಶೀಲತೆ ಮತ್ತು ನಿಗ್ರಾಹಕತೆ ಓದಿ.'),
        aim=W('To trace the B–H curve of a ferromagnetic material and find its retentivity and coercivity (a simplified model).', 'एक लौहचुंबकीय पदार्थ का B–H वक्र बनाना और उसकी धारणशीलता तथा निग्राहिता ज्ञात करना (सरलीकृत मॉडल)।', 'ಒಂದು ಫೆರೋಕಾಂತೀಯ ವಸ್ತುವಿನ B–H ವಕ್ರ ಎಳೆದು ಅದರ ಧಾರಣಶೀಲತೆ ಮತ್ತು ನಿಗ್ರಾಹಕತೆ ಕಂಡುಹಿಡಿಯುವುದು (ಸರಳೀಕೃತ ಮಾದರಿ).'),
        principle=W('In a ferromagnet B lags behind H: when H is brought back to zero some magnetism remains (retentivity), and a reverse field (coercivity) is needed to remove it. The loop’s area is the energy lost as heat per cycle. Soft iron has a narrow loop, steel a wide one. Here B = μ₀(H + Ms tanh((H ∓ Hc)/a)) stands in for the real material.', 'लौहचुंबक में B, H से पीछे रहता है: H को शून्य पर लाने पर कुछ चुंबकत्व बचा रहता है (धारणशीलता), और उसे हटाने के लिए उल्टा क्षेत्र (निग्राहिता) चाहिए। पाश का क्षेत्रफल प्रति चक्र ऊष्मा के रूप में खोई ऊर्जा है। नरम लोहे का पाश संकरा, स्टील का चौड़ा होता है। यहाँ B = μ₀(H + Ms tanh((H ∓ Hc)/a)) वास्तविक पदार्थ का स्थान लेता है।', 'ಫೆರೋಕಾಂತದಲ್ಲಿ B, H ಗಿಂತ ಹಿಂದುಳಿಯುತ್ತದೆ: H ಶೂನ್ಯಕ್ಕೆ ಬಂದಾಗ ಸ್ವಲ್ಪ ಕಾಂತತ್ವ ಉಳಿಯುತ್ತದೆ (ಧಾರಣಶೀಲತೆ); ಅದನ್ನು ತೆಗೆಯಲು ವಿರುದ್ಧ ಕ್ಷೇತ್ರ (ನಿಗ್ರಾಹಕತೆ) ಬೇಕು. ಕುಣಿಕೆಯ ವಿಸ್ತೀರ್ಣ ಪ್ರತಿ ಚಕ್ರಕ್ಕೆ ಉಷ್ಣವಾಗಿ ನಷ್ಟವಾದ ಶಕ್ತಿ. ಮೃದು ಕಬ್ಬಿಣದ ಕುಣಿಕೆ ಕಿರಿದು, ಉಕ್ಕಿನದು ಅಗಲ. ಇಲ್ಲಿ B = μ₀(H + Ms tanh((H ∓ Hc)/a)) ನಿಜ ವಸ್ತುವಿನ ಸ್ಥಾನದಲ್ಲಿದೆ.'),
        apparatus=[W('Soft-iron ring (toroid) with primary and secondary windings', 'प्राथमिक और द्वितीयक कुंडलन सहित नरम लोहे का वलय (टोरॉइड)', 'ಪ್ರಾಥಮಿಕ ಮತ್ತು ದ್ವಿತೀಯಕ ಸುರುಳಿಗಳ ಸಹಿತ ಮೃದು ಕಬ್ಬಿಣದ ಉಂಗುರ (ಟೊರಾಯ್ಡ್)'), W('Reversible DC supply and ammeter', 'प्रतिवर्ती DC आपूर्ति और ऐमीटर', 'ಹಿಮ್ಮುಖಗೊಳಿಸಬಹುದಾದ DC ಪೂರೈಕೆ ಮತ್ತು ಅಮ್ಮೀಟರ್'), W('Fluxmeter (or ballistic galvanometer)', 'फ़्लक्समीटर (या प्रक्षेप्य गैल्वेनोमीटर)', 'ಫ್ಲಕ್ಸ್‌ಮೀಟರ್ (ಅಥವಾ ಬ್ಯಾಲಿಸ್ಟಿಕ್ ಗ್ಯಾಲ್ವನೋಮೀಟರ್)'), RHEO],
        steps=[W('Demagnetise the ring, then raise H to its largest value (saturation).', 'वलय को विचुंबकित करें, फिर H को उसके सबसे बड़े मान (संतृप्ति) तक बढ़ाएँ।', 'ಉಂಗುರವನ್ನು ಕಾಂತರಹಿತಗೊಳಿಸಿ, ನಂತರ H ಅನ್ನು ಗರಿಷ್ಠ ಮೌಲ್ಯಕ್ಕೆ (ಸಂತೃಪ್ತಿ) ಏರಿಸಿ.'),
               W('Lower H in steps through zero to the largest negative value, recording B at each step.', 'H को चरणों में शून्य से होते हुए सबसे बड़े ऋणात्मक मान तक घटाएँ, हर चरण पर B लिखें।', 'H ಅನ್ನು ಹಂತಗಳಲ್ಲಿ ಶೂನ್ಯದ ಮೂಲಕ ಗರಿಷ್ಠ ಋಣ ಮೌಲ್ಯಕ್ಕೆ ಇಳಿಸಿ, ಪ್ರತಿ ಹಂತದಲ್ಲಿ B ದಾಖಲಿಸಿ.'),
               W('Raise H back to the positive maximum to close the loop.', 'पाश बंद करने के लिए H को फिर धनात्मक अधिकतम तक बढ़ाएँ।', 'ಕುಣಿಕೆ ಮುಚ್ಚಲು H ಅನ್ನು ಮತ್ತೆ ಧನ ಗರಿಷ್ಠಕ್ಕೆ ಏರಿಸಿ.'),
               W('Read the retentivity (B at H = 0) and the coercivity (H at B = 0).', 'धारणशीलता (H = 0 पर B) और निग्राहिता (B = 0 पर H) पढ़ें।', 'ಧಾರಣಶೀಲತೆ (H = 0 ನಲ್ಲಿ B) ಮತ್ತು ನಿಗ್ರಾಹಕತೆ (B = 0 ನಲ್ಲಿ H) ಓದಿ.'), CSV],
        precautions=[W('Change H in one direction at a time; never jump back and forth.', 'H को एक समय में एक ही दिशा में बदलें; आगे-पीछे न करें।', 'H ಅನ್ನು ಒಮ್ಮೆಗೆ ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಬದಲಿಸಿ; ಹಿಂದೆ-ಮುಂದೆ ಮಾಡಬೇಡಿ.'), W('Demagnetise the sample before starting.', 'शुरू करने से पहले नमूने को विचुंबकित करें।', 'ಆರಂಭಿಸುವ ಮೊದಲು ಮಾದರಿಯನ್ನು ಕಾಂತರಹಿತಗೊಳಿಸಿ.')],
        conclusion=W('B follows a closed loop that lags behind H; the ring keeps a large B at H = 0 (retentivity) but needs only a small reverse H to lose it (low coercivity), as for soft iron.', 'B एक बंद पाश पर चलता है जो H से पीछे रहता है; वलय H = 0 पर बड़ा B रखता है (धारणशीलता) पर उसे खोने के लिए छोटा उल्टा H काफ़ी है (कम निग्राहिता), जैसा नरम लोहे में होता है।', 'B, H ಗಿಂತ ಹಿಂದುಳಿಯುವ ಮುಚ್ಚಿದ ಕುಣಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತದೆ; ಉಂಗುರ H = 0 ನಲ್ಲಿ ದೊಡ್ಡ B ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ (ಧಾರಣಶೀಲತೆ), ಆದರೆ ಅದನ್ನು ಕಳೆಯಲು ಸಣ್ಣ ವಿರುದ್ಧ H ಸಾಕು (ಕಡಿಮೆ ನಿಗ್ರಾಹಕತೆ), ಮೃದು ಕಬ್ಬಿಣದಂತೆ.'),
        viva=[Q(W('Why is soft iron used for transformer cores?', 'ट्रांसफ़ॉर्मर के क्रोड में नरम लोहा क्यों प्रयोग होता है?', 'ಪರಿವರ್ತಕದ ತಿರುಳಿಗೆ ಮೃದು ಕಬ್ಬಿಣ ಏಕೆ?'), W('Its narrow loop means little energy is lost each cycle.', 'इसका संकरा पाश प्रति चक्र कम ऊर्जा हानि दर्शाता है।', 'ಅದರ ಕಿರಿದಾದ ಕುಣಿಕೆ ಪ್ರತಿ ಚಕ್ರದಲ್ಲಿ ಕಡಿಮೆ ಶಕ್ತಿ ನಷ್ಟ ಸೂಚಿಸುತ್ತದೆ.')),
              Q(W('Which material makes a good permanent magnet?', 'स्थायी चुंबक के लिए कौन-सा पदार्थ अच्छा है?', 'ಶಾಶ್ವತ ಕಾಂತಕ್ಕೆ ಯಾವ ವಸ್ತು ಉತ್ತಮ?'), W('One with high retentivity and high coercivity, like hard steel or alnico.', 'उच्च धारणशीलता और उच्च निग्राहिता वाला, जैसे कठोर स्टील या ऐल्निको।', 'ಹೆಚ್ಚು ಧಾರಣಶೀಲತೆ ಮತ್ತು ಹೆಚ್ಚು ನಿಗ್ರಾಹಕತೆಯದು, ಗಟ್ಟಿ ಉಕ್ಕು ಅಥವಾ ಆಲ್ನಿಕೋ ಹಾಗೆ.')),
              Q(W('What does the area of the loop represent?', 'पाश का क्षेत्रफल क्या दर्शाता है?', 'ಕುಣಿಕೆಯ ವಿಸ್ತೀರ್ಣ ಏನನ್ನು ಸೂಚಿಸುತ್ತದೆ?'), W('Energy lost as heat per unit volume per cycle.', 'प्रति चक्र प्रति इकाई आयतन ऊष्मा के रूप में खोई ऊर्जा।', 'ಪ್ರತಿ ಚಕ್ರಕ್ಕೆ ಪ್ರತಿ ಏಕಮಾನ ಘನಫಲಕ್ಕೆ ಉಷ್ಣವಾಗಿ ನಷ್ಟವಾದ ಶಕ್ತಿ.'))])
